/**
 * The bottom bar spaces its icons evenly however many are shown. It was a grid of a fixed seven
 * columns: signed out (no Harness icon) the bar showed six icons and left the seventh column empty
 * at the end, so the same bar looked evenly spaced only when signed in. Founder report, 2026-10-12.
 */
import { describe, expect, it } from 'vitest';
import { SHELL_CSS } from './presenter-shell-styles.js';

const chromeRule = (): string => {
  const rule = /\.reticle-toolbar-chrome\{([^}]*)\}/.exec(SHELL_CSS);
  if (null === rule) throw new Error('no .reticle-toolbar-chrome rule');
  return rule[1] ?? '';
};

describe('the HUD bottom bar', () => {
  it('never fixes a column count, so a missing icon leaves no gap at the end', () => {
    expect(chromeRule()).not.toMatch(/grid-template-columns\s*:\s*repeat\(\s*\d+/);
  });

  it('gives every shown icon one equal column', () => {
    expect(chromeRule()).toMatch(/grid-auto-flow\s*:\s*column/);
    expect(chromeRule()).toMatch(/grid-auto-columns\s*:\s*minmax\(0,\s*1fr\)/);
  });
});

/**
 * A run must say WHICH agent produced it, and must never invent one.
 */
import { afterEach, describe, expect, it } from 'vitest';
import {
  clearMcpClientIdentityHook,
  mcpClientIdentity,
  setMcpClientIdentityHook,
} from './client-identity.js';

afterEach(() => clearMcpClientIdentityHook());

describe('mcpClientIdentity', () => {
  it('reports the client the handshake actually named', () => {
    setMcpClientIdentityHook(() => ({ name: 'claude-code', version: '1.4.2' }));
    expect(mcpClientIdentity()).toStrictEqual({ name: 'claude-code', version: '1.4.2' });
  });

  it('distinguishes one agent from another — the whole point of recording it', () => {
    setMcpClientIdentityHook(() => ({ name: 'cursor-vscode' }));
    expect(mcpClientIdentity().name).toBe('cursor-vscode');
  });

  it('reports NOTHING when no peer introduced itself, rather than guessing a vendor', () => {
    expect(mcpClientIdentity()).toStrictEqual({});
    setMcpClientIdentityHook(() => undefined);
    expect(mcpClientIdentity()).toStrictEqual({});
    setMcpClientIdentityHook(() => ({ name: '' }));
    expect(mcpClientIdentity()).toStrictEqual({});
  });

  it('bounds what a client can write into an artifact', () => {
    setMcpClientIdentityHook(() => ({ name: 'x'.repeat(500), version: 'v'.repeat(500) }));
    const id = mcpClientIdentity();
    expect(id.name).toHaveLength(64);
    expect(id.version).toHaveLength(32);
  });

  it('a throwing hook never breaks the caller — this is descriptive, not load-bearing', () => {
    setMcpClientIdentityHook(() => {
      throw new Error('transport died mid-handshake');
    });
    expect(mcpClientIdentity()).toStrictEqual({});
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import * as http from 'node:http';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ReticleEnv, MCP_SSE_PATH } from '@reticlehq/core';
import { removeTempDir } from './machine/temp-dir.js';
import { startDaemon, type RunningServer } from './index.js';
import { FakeBrowser, waitUntil } from './portal/bridge/bridge.test-harness.js';

/**
 * Regression for #1138: a live browser session is stronger evidence that an app has connected than
 * the durable "connected before" memory, which can be empty or stale for a project the plugin wired
 * without writing `.reticle.json` (see connection-memory.ts's KNOWN LIMIT). Before the fix, the MCP
 * `initialize` instructions asked ONLY the durable memory, so a session that is live *right now* was
 * still told "no app has ever connected" and led with the first-install steps (`init`, restart,
 * load) — reported from the field as an agent redundantly (and, with a human at the keyboard,
 * destructively) restarting a dev server that was fine.
 */

interface SseFrame {
  event: string;
  data: string;
}

function openSse(port: number): Promise<{
  waitFor: (match: (f: SseFrame) => boolean, timeoutMs?: number) => Promise<SseFrame>;
  close: () => void;
}> {
  return new Promise((resolve, reject) => {
    const req = http.get({ host: '127.0.0.1', port, path: MCP_SSE_PATH, agent: false }, (res) => {
      const frames: SseFrame[] = [];
      const waiters: { match: (f: SseFrame) => boolean; resolve: (f: SseFrame) => void }[] = [];
      let buffer = '';
      res.setEncoding('utf8');
      res.on('data', (chunk: string) => {
        buffer += chunk;
        const parts = buffer.split('\n\n');
        buffer = parts.pop() ?? '';
        for (const part of parts) {
          let event = 'message';
          const data: string[] = [];
          for (const line of part.split('\n')) {
            if (line.startsWith('event:')) event = line.slice('event:'.length).trim();
            else if (line.startsWith('data:')) data.push(line.slice('data:'.length).trim());
          }
          const frame: SseFrame = { event, data: data.join('\n') };
          frames.push(frame);
          for (let i = waiters.length - 1; i >= 0; i -= 1) {
            const waiter = waiters[i];
            if (waiter !== undefined && waiter.match(frame)) {
              waiter.resolve(frame);
              waiters.splice(i, 1);
            }
          }
        }
      });
      resolve({
        waitFor: (match, timeoutMs = 5000) =>
          new Promise<SseFrame>((settle, fail) => {
            const already = frames.find(match);
            if (already !== undefined) {
              settle(already);
              return;
            }
            const timer = setTimeout(
              () => fail(new Error('no SSE frame matched within the budget')),
              timeoutMs,
            );
            waiters.push({
              match,
              resolve: (f) => {
                clearTimeout(timer);
                settle(f);
              },
            });
          }),
        close: () => req.destroy(),
      });
    });
    req.on('error', reject);
  });
}

function post(port: number, path: string, body: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        host: '127.0.0.1',
        port,
        path,
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) },
      },
      (res) => {
        let out = '';
        res.setEncoding('utf8');
        res.on('data', (c: string) => (out += c));
        res.on('end', () => resolve({ status: res.statusCode ?? 0, body: out }));
      },
    );
    req.on('error', reject);
    req.end(body);
  });
}

const rpc = (id: number, method: string, params?: unknown): string =>
  JSON.stringify({ jsonrpc: '2.0', id, method, ...(params === undefined ? {} : { params }) });

function idOf(frame: SseFrame): number | undefined {
  try {
    const id = (JSON.parse(frame.data) as { id?: unknown }).id;
    return 'number' === typeof id ? id : undefined;
  } catch {
    return undefined;
  }
}

describe('the initialize instructions when a session is live but durable memory is empty', () => {
  let server: RunningServer | undefined;
  let dir: string | undefined;
  let savedStateDir: string | undefined;

  afterEach(async () => {
    await server?.close();
    server = undefined;
    if (dir !== undefined) await removeTempDir(dir);
    dir = undefined;
    if (savedStateDir === undefined) delete process.env[ReticleEnv.STATE_DIR];
    else process.env[ReticleEnv.STATE_DIR] = savedStateDir;
    savedStateDir = undefined;
  });

  it('does not lead with the first-install steps once a browser session is connected', async () => {
    savedStateDir = process.env[ReticleEnv.STATE_DIR];
    dir = await mkdtemp(join(tmpdir(), 'reticle-mcp-live-session-'));
    // An empty, freshly-made state directory: `hasAnyProjectConnectedBefore` has nothing to find here,
    // which is the "durable memory says no" half of the bug.
    process.env[ReticleEnv.STATE_DIR] = join(dir, 'state');
    const root = join(dir, '.reticle');

    server = await startDaemon({
      port: 0,
      reticleRoot: root,
      pairingTokenDir: <REDACTED> 'token'),
      token: '<REDACTED>',
      now: () => 1_700_000_000_000,
    });
    const port = await server.bridge.ready;

    // The "live session" half: a browser is connected RIGHT NOW, which the durable memory alone
    // cannot see.
    const browser = new FakeBrowser(port, 'sess-live', false, 'pair-me');
    await browser.open();
    await waitUntil(() => 1 === server?.bridge.sessions.count());

    const sse = await openSse(port);
    const endpoint = await sse.waitFor((f) => 'endpoint' === f.event);
    await post(
      port,
      endpoint.data,
      rpc(1, 'initialize', {
        protocolVersion: '2024-11-05',
        capabilities: {},
        clientInfo: { name: 'test-client', version: '0' },
      }),
    );
    const reply = await sse.waitFor((f) => 1 === idOf(f));
    const instructions =
      (JSON.parse(reply.data) as { result?: { instructions?: string } }).result?.instructions ?? '';

    expect(
      instructions,
      'a live session is stronger evidence than empty durable memory, but the handshake still opened with the first-install steps',
    ).not.toContain('no app has ever connected');
    expect(instructions.startsWith('FIRST:')).toBe(false);

    sse.close();
    browser.close();
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import { AgentClient, LaunchMethod } from '@reticlehq/core/telemetry';
import { forgetAgents, noteAgentAttached, runAsAgent } from '@/hooks/coding-agents.js';
import { currentAgentClient, envAgentClient, launchMethodOf } from './agent-client.js';

afterEach(() => forgetAgents());

describe('currentAgentClient', () => {
  it('normalises the handshake name to a closed value, never the raw text', () => {
    noteAgentAttached('a', 'claude-code');
    expect(currentAgentClient({})).toBe(AgentClient.CLAUDE_CODE);
  });

  it('reports a client it does not know as other', () => {
    noteAgentAttached('a', 'my-secret-internal-agent');
    expect(currentAgentClient({})).toBe(AgentClient.OTHER);
  });

  it('credits the call to the connection it came over when two agents are attached', async () => {
    noteAgentAttached('a', 'claude-code');
    noteAgentAttached('b', 'cursor-vscode');
    expect(currentAgentClient({})).toBeUndefined();
    expect(await runAsAgent('b', () => Promise.resolve(currentAgentClient({})))).toBe(
      AgentClient.CURSOR,
    );
  });

  it('falls back to the marker an agent sets on what it spawns', () => {
    expect(currentAgentClient({ CLAUDECODE: '1' })).toBe(AgentClient.CLAUDE_CODE);
    expect(envAgentClient({ CURSOR_TRACE_ID: 'x' })).toBe(AgentClient.CURSOR);
    expect(envAgentClient({})).toBeUndefined();
  });

  it('prefers the handshake over the environment', () => {
    noteAgentAttached('a', 'codex-mcp-client');
    expect(currentAgentClient({ CLAUDECODE: '1' })).toBe(AgentClient.CODEX);
  });
});

describe('launchMethodOf', () => {
  it('buckets the entry path, which itself never leaves', () => {
    expect(
      launchMethodOf('/Users/a/.npm/_npx/abc/node_modules/@reticlehq/server/dist/cli.js'),
    ).toBe(LaunchMethod.NPX);
    expect(launchMethodOf('/usr/local/lib/node_modules/@reticlehq/server/dist/cli.js')).toBe(
      LaunchMethod.GLOBAL,
    );
    expect(
      launchMethodOf(
        'C:\\Users\\a\\AppData\\Roaming\\npm\\node_modules\\@reticlehq\\server\\cli.js',
      ),
    ).toBe(LaunchMethod.GLOBAL);
    expect(launchMethodOf('/repo/app/node_modules/@reticlehq/server/dist/cli.js')).toBe(
      LaunchMethod.PROJECT,
    );
    expect(launchMethodOf('/repo/reticle/server/dist/cli.js')).toBe(LaunchMethod.OTHER);
    expect(launchMethodOf(undefined)).toBe(LaunchMethod.OTHER);
  });
});

import { describe, expect, it } from 'vitest';
import { EventType } from '@reticlehq/core';
import { buildEvent } from './reticle.js';

/**
 * Every event says which document it was observed under.
 *
 * Without it, evidence is scoped by time and buffer capacity alone, so a request from a previous
 * document — or a previous run of the app — can be cited against an action taken now. The stamp is
 * what lets the server refuse that evidence instead of reporting it.
 *
 * Stamped in `buildEvent` because it is the one place every event passes through. Anywhere else and
 * an observer added later would emit unstamped events, which read as "current" by design and would
 * therefore reintroduce the defect silently for exactly one event type.
 */

const base = {
  seq: 1,
  t: 10,
  type: EventType.CONSOLE_ERROR,
  sessionId: 's1',
  data: {},
};

describe('buildEvent stamps the document', () => {
  it('carries the document id it was given', () => {
    expect(buildEvent({ ...base, documentId: 'doc12345' }).documentId).toBe('doc12345');
  });

  it('omits the field rather than inventing one when no document is known', () => {
    // Absence is read as "current document" downstream, so a fabricated id would be worse than none:
    // it would silently exclude real evidence instead of merely failing to scope it.
    expect(buildEvent(base).documentId).toBeUndefined();
  });

  it('leaves every other field of the envelope alone', () => {
    const event = buildEvent({ ...base, ref: 'e7', documentId: 'doc12345' });
    expect(event.seq).toBe(1);
    expect(event.t).toBe(10);
    expect(event.type).toBe(EventType.CONSOLE_ERROR);
    expect(event.sessionId).toBe('s1');
    expect(event.ref).toBe('e7');
  });
});

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPO_ROOT } from '@/machine/repo-root.js';

/**
 * How much an agent has to read before it can do anything.
 *
 * SKILL.md is the first thing an agent loads, every session, before its first action. Its length is
 * therefore a real cost paid by every user, and nothing measured it. Meanwhile the number that
 * matters to a person is a stopwatch: onboarding was measured in the field at nearly eighteen
 * minutes to a first result, against a target of two.
 *
 * This file cannot measure minutes. It measures the thing under our control that feeds them, and
 * pins it so it cannot quietly grow while the real fix is planned.
 *
 * The structural point is the second test. The file covers two unrelated situations in one
 * document: setting Reticle up, and using it once it is set up. Setting up happens once. Using it
 * happens every session afterwards. So the common case reads the whole file to reach the half that
 * applies to it, and pays for the other half forever.
 *
 * The file already knows this. It has a "Which path am I on" section, and that section sits eighty
 * lines after the reader started, which is the whole problem in one sentence. Splitting by
 * situation is the fix; these numbers are how anyone will know whether the split actually worked.
 */
const SKILL = readFileSync(join(REPO_ROOT, 'SKILL.md'), 'utf8');

/**
 * The size ratchet, in bytes.
 *
 * MEASURED 2026-09-10, after the split: 187 lines, 12,540 bytes. Was 19,918 before the setup half
 * moved to `docs/skill-setup.md` — a 37% cut to what every agent reads, every session, with no
 * content deleted. The budget is today's size plus about 2%: room to fix a typo, none to add a
 * section.
 *
 * Going over is not forbidden, it is a DECISION. Move the number and write the reason here, the way
 * the tool-surface ratchet does. Coming in well under, move it down and keep the win.
 *
 * RAISED to 13,200 for the replay-first ladder, and this is the measurement that bought it: across
 * 13 agent cells and 323 tool calls, with 29 saved flows sitting on disk the whole time, replay was
 * invoked ZERO times. The engine was built, tested and reachable, and nothing an agent reads ever
 * mentioned it. What the extra bytes buy is the order of operations, which is the whole saving: a
 * covered journey re-verifies for a few hundred tokens where driving the same one measured
 * 201k-325k. Paid for in part rather than simply appended: two table rows the prose already covered
 * were cut, and the sections around them were tightened instead of extended. If a future raise
 * cannot show a number like that, cut a section instead of moving this again.
 */
/*
 * Set 2026-10-12 by the founder's decision, as a budget for about a year of work rather than the
 * measurement plus a sliver: it was re-raised dozens of times in a month, which made the check churn
 * instead of a signal. Measured 13,195 B (agents read it, so ~21%) at 81e046201. Review it once a year, not per change; a
 * sudden jump inside it is still worth a look in review.
 */
const SKILL_BYTE_BUDGET = 16_000;

/** Where the file stops being general advice and starts being about one situation or the other. */
const SETUP_HEADING = '\n# SETUP\n';
const VERIFY_HEADING = '\n# VERIFY\n';

const bytesOf = (text: string): number => Buffer.byteLength(text, 'utf8');

describe('the skill file is a cost every session pays', () => {
  it('has not grown past its budget', () => {
    // A budget alone would pass on an empty file, which is how a broken read looks like a saving.
    expect(bytesOf(SKILL), 'SKILL.md read as empty or near-empty').toBeGreaterThan(5_000);
    expect(
      bytesOf(SKILL),
      `SKILL.md is ${String(bytesOf(SKILL))} B, budget ${String(SKILL_BYTE_BUDGET)} B. Every agent ` +
        'reads this before its first action, every session. Shorten something, or raise the budget ' +
        'deliberately and write the reason next to it.',
    ).toBeLessThanOrEqual(SKILL_BYTE_BUDGET);
  });

  it('records how much an already-installed agent reads but does not need', () => {
    const setupAt = SKILL.indexOf(SETUP_HEADING);
    const verifyAt = SKILL.indexOf(VERIFY_HEADING);
    expect(setupAt, 'SKILL.md has no SETUP section — this test needs updating').toBeGreaterThan(0);
    expect(verifyAt, 'SKILL.md has no VERIFY section — this test needs updating').toBeGreaterThan(
      setupAt,
    );

    const setupHalf = bytesOf(SKILL.slice(setupAt, verifyAt));
    const wastedShare = setupHalf / bytesOf(SKILL);

    // The split landed, and this is the number that shows it.
    //
    // BEFORE: preamble 6,100 B, setup half 7,896 B, verify half 5,922 B. An agent that was already
    // set up read 19,918 B to use 12,022 of them, paying 39.6% for instructions about a job it
    // finished once.
    //
    // AFTER: the setup half is a short pointer to `docs/skill-setup.md`, which ships in the package
    // (`files` includes `docs`), so it is a local read rather than a network call for the one
    // session that needs it. No content was deleted; it moved.
    //
    // The bound stays low so the setup half cannot quietly grow back inside this file.
    expect(
      wastedShare,
      `the setup half is ${String(Math.round(wastedShare * 100))}% of SKILL.md (${String(setupHalf)} B). ` +
        'An agent that is already set up reads all of it for nothing. If you have split the file by ' +
        'situation, this number should have dropped sharply — update the bound and keep the win.',
    ).toBeLessThanOrEqual(0.12);
  });
});

import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPO_ROOT } from '@/machine/repo-root.js';

/**
 * A page SKILL.md says is "on disk beside this file" has to actually be there.
 *
 * The skill file tells an agent it can open some pages locally instead of fetching them. That is
 * worth saying: a field install lost two minutes to repeated web fetches, and the page an agent
 * reaches for most is the troubleshooting one -- read at the moment something is already not
 * working, which is the worst moment to depend on the network.
 *
 * The promise is only as good as the path. `docs/` is at the repository root here and at
 * `server/docs` in the published package, the extensions are a mix of `.md` and `.mdx`, and
 * `pack-docs.mjs` copies rather than renames. A path that is right in one of those places and wrong
 * in the other fails in the copy every user downloads, and silently -- the agent simply fetches
 * instead, or gives up on the page entirely.
 */
const SKILL = join(REPO_ROOT, 'SKILL.md');

/** Every `docs/...` path SKILL.md names as available on disk. */
function localDocPaths(): string[] {
  const text = readFileSync(SKILL, 'utf8');
  return [
    ...new Set([...text.matchAll(/`(docs\/[\w./-]+\.mdx?)`/g)].map((m) => m[1] ?? '')),
  ].sort();
}

describe('the local copies SKILL.md promises are real', () => {
  const paths = localDocPaths();

  it('names at least one', () => {
    // Without this the check below would pass by having nothing to look for.
    expect(paths.length).toBeGreaterThan(0);
  });

  it('every one exists', () => {
    expect(
      paths.filter((path) => !existsSync(join(REPO_ROOT, path))),
      'SKILL.md tells an agent these ship on disk beside it, and they do not exist. Either fix the ' +
        'path (mind .md against .mdx) or stop promising the local copy.',
    ).toEqual([]);
  });

  it('and is published, so the promise holds in the tarball too', () => {
    // The repository is not the thing the promise is made to. `files` in the manifest decides what a
    // user actually receives, and a page that exists here and ships nowhere is the same broken
    // promise arriving by a different route.
    const manifest = JSON.parse(
      readFileSync(join(REPO_ROOT, 'server', 'package.json'), 'utf8'),
    ) as { files?: string[] };
    expect(manifest.files ?? []).toContain('docs');
  });
});

import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { REPO_ROOT } from '@/machine/repo-root.js';

/**
 * No bench-app source may fetch a RELATIVE `/api/...` URL.
 *
 * bench-app has no Vite dev-server proxy, so a relative API path never reaches `apps/api` on :8787.
 * It hits the dev server, matches nothing, and comes back as the SPA fallback: `index.html` with
 * **status 200**. The request does not error. It succeeds, with the wrong body, silently.
 *
 * That is not hypothetical. `Hostile.tsx` fired `fetch('/api/broken/500')` behind a button labelled
 * "Fire failing request", and the fixture's own docstring named the acceptance it exists to prove:
 *
 *     "the single failed request must survive the flood instead of being pushed out of the
 *      ring buffer by thousands of low-signal churn events"
 *
 * There was no failed request. The flood was being tested against a 200, so the acceptance was
 * exercising a weaker claim than the one written down — and priority eviction exists specifically
 * to protect FAILURES, which is the case that was never run. Every other call site in bench-app
 * already used `API_BASE`; this one was the outlier, and nothing could see it, because a 200 is
 * exactly what a passing test looks like.
 *
 * Placed in the unit gate rather than the e2e battery for the same reason as
 * `e2e-surface-drift.test.ts`: the battery needs three servers and minutes, this needs a substring,
 * and the pattern in this repo is unambiguous — every rule a machine enforces has held, and every
 * rule left to prose has been violated.
 */
const REPO = REPO_ROOT;
const SRC = join(REPO, 'apps', 'bench-app', 'src');

/**
 * `fetch('/api/…')` in any quote style — the shape that silently resolves to the SPA fallback.
 *
 * NOT global. `.test()` on a `/g` regex advances `lastIndex` and resumes from there on the next
 * call, so once one file matched, the following file was searched from an offset into a string it
 * has nothing to do with — and a second offender was skipped. A guard that stops catching things
 * after its first hit is worse than no guard, because the green is now evidence of nothing.
 */
const RELATIVE_API_FETCH = /fetch\(\s*['"`]\/api\//;

function sourceFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) {
      out.push(...sourceFiles(full));
      continue;
    }
    if (/\.tsx?$/.test(entry)) out.push(full);
  }
  return out;
}

describe('bench-app requests reach the API', () => {
  it('no source fetches a relative /api/ path — there is no dev-server proxy', () => {
    const files = sourceFiles(SRC);
    // The denominator. Moving the fixture's components out of `src/` leaves the directory present
    // and empty of `.tsx`, and an empty offender list then means "nothing was read", not "nothing
    // is wrong". The defect behind this guard is a relative `/api/` fetch resolving to a 200 SPA
    // fallback — a benchmark false green, which is the expensive kind to not notice.
    expect(files.length, `no source file under ${relative(REPO, SRC)}`).toBeGreaterThan(0);
    const offenders = files
      .filter((file) => RELATIVE_API_FETCH.test(readFileSync(file, 'utf8')))
      .map((file) => relative(REPO, file));
    expect(offenders).toEqual([]);
  });

  it('the guard actually matches the shape it is meant to catch', () => {
    // Without this, a broken regex makes the check above pass forever while enforcing nothing —
    // which is the exact failure it was written to prevent, one level up.
    //
    // Against the REAL constant, not a copy of it pasted here: a self-test that retypes the pattern
    // proves the pattern in the test file, and goes on passing while the one actually used drifts.
    expect(RELATIVE_API_FETCH.test("void fetch('/api/broken/500')")).toBe(true);
    expect(RELATIVE_API_FETCH.test('await fetch(`${API_BASE}/api/broken/500`)')).toBe(false);
  });

  it('finds a second offender, not just the first', () => {
    // The `/g` + `.test()` bug this pins: a stateful regex carries `lastIndex` between calls, so the
    // scan above went blind to every file after the first match. Two identical strings in a row is
    // the whole reproduction.
    const offender = "void fetch('/api/broken/500')";
    expect(RELATIVE_API_FETCH.test(offender)).toBe(true);
    expect(
      RELATIVE_API_FETCH.test(offender),
      'the guard must not go blind after its first hit',
    ).toBe(true);
  });
});

import { describe, expect, it } from 'vitest';
import { createMcpServer } from './mcp.js';
import { advertisedTools } from './mcp.js';
import { TOOL_SURFACE } from '@/surface/tools/tool-surface.js';
import { TOOLS, type ToolDef, type ToolDeps } from '@/surface/tools/tools.js';
import { ReticleTool } from '@reticlehq/core';

/**
 * A consumer embedding this engine may serve its own tools alongside ours, on one surface.
 *
 * The tool surface is the product's front door, and the rule that governs it — there is ONE surface,
 * not a menu — is about US not shipping variants. It was never meant to stop a SERVICE built on this
 * engine from adding a tool that answers out of something this package has never heard of. Before
 * this, `createMcpServer` read the module-level `TOOLS` directly, so the only way to add one was to
 * edit that array: a fork, to append to a list.
 *
 * The composed list is threaded through instead of read, which also settles the harder half — the
 * `reticle_run` hatch and the unadvertised-tool help both need the FULL table, and a consumer tool
 * missing from either is a tool the agent is told does not exist.
 *
 * The profile trim does not apply to consumer tools, and that is deliberate. A profile is a decision
 * about how much of OUR 48-tool table is worth re-sending every turn; a consumer that appended three
 * tools has already made that decision by appending them. Filtering them by our `CORE_TOOL_NAMES`
 * would silently drop every one — the list is ours, and their names were never going to be in it.
 */

const CONSUMER_TOOL: ToolDef = {
  name: 'consumer_recall',
  description: 'Answers out of a store this package does not know about.',
  inputSchema: {},
  handler: () => Promise.resolve({ answer: 'remembered' }),
};

const depsForTest = (): ToolDeps =>
  ({ sessions: { resolve: () => ({ id: 'x' }) } }) as unknown as ToolDeps;

async function openServer(tools: readonly ToolDef[]): Promise<{
  names: string[];
  call: (name: string) => Promise<unknown>;
  close: () => Promise<void>;
}> {
  const { InMemoryTransport } = await import('@modelcontextprotocol/sdk/inMemory.js');
  const { Client } = await import('@modelcontextprotocol/sdk/client/index.js');
  const server = createMcpServer(depsForTest(), TOOL_SURFACE.DEFAULT, false, tools);
  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
  await server.connect(serverTransport);
  const client = new Client({ name: 'c', version: '0' });
  await client.connect(clientTransport);
  const listed = await client.listTools();
  return {
    names: listed.tools.map((t) => t.name),
    call: (name: string) => client.callTool({ name, arguments: {} }),
    close: async () => {
      await client.close();
      await server.close();
    },
  };
}

describe('a composed tool surface', () => {
  it('advertises a consumer tool over the wire, under the default profile', async () => {
    const { names, close } = await openServer([...TOOLS, CONSUMER_TOOL]);
    try {
      expect(names).toContain(CONSUMER_TOOL.name);
      // Ours are still trimmed by the profile — appending a tool must not turn the default surface
      // into the full one, which would silently multiply every agent's per-turn bill.
      expect(names).toContain(ReticleTool.TOOLS);
      expect(names.length).toBeLessThan(TOOLS.length);
    } finally {
      await close();
    }
  });

  it('dispatches a call to the consumer handler', async () => {
    const { call, close } = await openServer([...TOOLS, CONSUMER_TOOL]);
    try {
      const result = (await call(CONSUMER_TOOL.name)) as { structuredContent?: unknown };
      expect(JSON.stringify(result)).toContain('remembered');
    } finally {
      await close();
    }
  });

  it('defaults to the shipped table, so every existing caller is unchanged', async () => {
    const { names, close } = await openServer(TOOLS);
    try {
      expect(names).not.toContain(CONSUMER_TOOL.name);
      expect(names).toContain(ReticleTool.TOOLS);
    } finally {
      await close();
    }
  });

  it('profile-trims our tools while keeping every consumer tool', () => {
    const composed = advertisedTools(TOOL_SURFACE.DEFAULT, [...TOOLS, CONSUMER_TOOL]);
    const ours = advertisedTools(TOOL_SURFACE.DEFAULT);

    expect(composed.map((t) => t.name)).toContain(CONSUMER_TOOL.name);
    // Exactly one more than ours: the consumer tool, and nothing of ours smuggled back in.
    expect(composed.length).toBe(ours.length + 1);
  });

  // The refusal at mcp.ts had no test: only the pure helper that finds the keys was covered, so
  // deleting the check itself left every test green while any consumer tool could hand the agent
  // `verified: "yes"` with none of Reticle's evidence behind it.
  it('refuses a consumer tool that tries to hand the agent a verdict', async () => {
    const minting: ToolDef = {
      name: 'consumer_minting',
      description: 'Claims a verdict it did not earn.',
      inputSchema: {},
      handler: () => Promise.resolve({ verified: 'yes' }),
    };
    const { call, close } = await openServer([...TOOLS, minting]);
    try {
      const result = (await call(minting.name)) as {
        isError?: boolean;
        content?: { text?: string }[];
      };
      expect(result.isError).toBe(true);
      expect(result.content?.[0]?.text).toContain('verified');
      expect(JSON.stringify(result)).not.toContain('"verified":"yes"');
    } finally {
      await close();
    }
  });
});

/**
 * The two SDK internals `mcp.ts` monkey-patches must still be there.
 *
 * `@modelcontextprotocol/sdk` is pinned `^1.30.0`, so a MINOR bump installs itself without asking.
 * Both patches reach past the public API — `validateToolInput` for readable argument errors,
 * `_requestHandlers` for the "known but un-advertised" help — and both bail out with a bare `return`
 * when their shape is missing. A rename upstream therefore turns two shipped features off with no
 * error, no red test and, until now, no log line. The `_requestHandlers` one cost a user a long run
 * of false failures the first time it was ABSENT; a silent regression to that state is the same bug.
 *
 * So this suite fails at the fast gate, on the version bump, in CI — not in someone's session.
 * It asserts the shapes on a real SDK server built the way `createMcpServer` builds one, and is
 * deliberately about the SHAPE only: whether the patches behave correctly is the business of
 * `mcp.test.ts` and `unadvertised-tool-over-transport.test.ts`.
 */

import { describe, expect, it } from 'vitest';
import { createMcpServer, CALL_TOOL_METHOD } from './mcp.js';
import { TOOL_SURFACE } from '@/surface/tools/tool-surface.js';
import type { ToolDeps } from '@/surface/tools/tools.js';

const toolDepsForTest = (): ToolDeps =>
  ({ sessions: { resolve: () => ({ id: 'x' }) } }) as unknown as ToolDeps;

describe('the private MCP SDK shapes both monkey-patches depend on', () => {
  it('still exposes validateToolInput, or friendly argument errors are silently off', () => {
    const server = createMcpServer(toolDepsForTest(), TOOL_SURFACE.DEFAULT);
    const target = server as unknown as { validateToolInput?: unknown };
    expect(
      typeof target.validateToolInput,
      'SDK renamed validateToolInput — mcp.ts installFriendlyArgErrors is now a no-op',
    ).toBe('function');
  });

  it('still exposes _requestHandlers with a tools/call entry, or unadvertised help is silently off', () => {
    const server = createMcpServer(toolDepsForTest(), TOOL_SURFACE.DEFAULT);
    const inner = server.server as unknown as { _requestHandlers?: Map<string, unknown> };
    const handlers = inner._requestHandlers;
    expect(
      handlers instanceof Map,
      'SDK renamed _requestHandlers — mcp.ts unadvertised-tool help is now a no-op',
    ).toBe(true);
    // The dispatcher is installed lazily on the first registerTool, so its absence here means the
    // method name moved, not that registration was skipped.
    expect(
      handlers?.get(CALL_TOOL_METHOD),
      `SDK no longer dispatches '${CALL_TOOL_METHOD}' — unadvertised-tool help is now a no-op`,
    ).toBeTypeOf('function');
  });
});

/**
 * A message Reticle wrote about the caller's arguments must never ask for a bug report.
 *
 * `RULES` is a denylist of message shapes, so every message we author defaults to "unrecognized",
 * and unrecognized attaches `FEEDBACK_ASK` — "this may be a defect in Reticle... call
 * reticle_feedback with a root-cause analysis before moving on".
 *
 * That default has now been patched FOUR times, each time for one more spelling of the same idea,
 * and the file records three of them: the browser's `executeAction` guards ("ALL of them used to
 * fall through to the feedback ask"), the destructive-action block, and the three spellings of
 * "potentially destructive ... blocked" where the rule matched one and "two thirds of the same
 * deliberate refusal still read as a possible defect".
 *
 * Measured live on 2026-08-23, the fourth: a drag naming an unresolvable `toRef` returns
 *
 *   error:    "drag target 'e999999' did not resolve to an element — pass a ref from
 *              reticle_snapshot or reticle_query as args.toRef (alias: args.target)"
 *   feedback: "This error is not one Reticle recognizes, which means it may be a defect in
 *              Reticle rather than in the app..."
 *
 * The message teaches the exact fix, and the payload immediately tells the agent the fix might be
 * a bug worth reporting. That costs a turn and files a false report about correct behaviour — and
 * this refusal is itself the fix for a previously-shipped drag false green.
 *
 * The catch-all it missed requires `reticle_x { ... }` WITH braces AND requires/must/expected. A
 * message that names a `reticle_*` tool or an `args.*` parameter is ours whatever its punctuation,
 * so the rule keys on that instead of on one sentence shape.
 */

import { describe, expect, it } from 'vitest';
import { recoveryFor } from './error-recovery.js';
import { resolveTargetRef } from './act/resolve-target.js';

/** The exact string measured from a live daemon. */
const DRAG =
  "drag target 'e999999' did not resolve to an element — pass a ref from reticle_snapshot or " +
  'reticle_query as args.toRef (alias: args.target)';

describe('a message we authored about the caller is recognized as ours', () => {
  it('recognizes the live drag refusal', () => {
    expect(recoveryFor(DRAG)).toBeDefined();
  });

  it('names a tool without braces and is still ours', () => {
    expect(recoveryFor('pass a ref from reticle_snapshot as args.toRef')).toBeDefined();
  });

  it('names an args.* parameter and is still ours', () => {
    expect(recoveryFor('upload needs args.path pointing at a file on disk')).toBeDefined();
  });

  /** The shape the old catch-all already handled must keep working. */
  it('keeps recognizing the braced form', () => {
    expect(recoveryFor('reticle_query { by } requires a string `value`')).toBeDefined();
  });

  /**
   * The FIFTH spelling, measured live: a first run on a machine with no key answered
   *
   *   error:    "No model configured to drive the app: set ANTHROPIC_API_KEY to let Reticle explore
   *              it for you. Without it, flows are recorded by your own coding agent..."
   *   feedback: "This error is not one Reticle recognizes, which means it may be a defect in
   *              Reticle rather than in the app..."
   *
   * It names no tool and no `args.*`, so the catch-all above missed it — the message states the
   * exact fix AND tells the reader it might be our bug. Keyed on the instruction, "set <VARIABLE>",
   * because a message telling the caller to set something is one we wrote about their configuration.
   */
  it('tells the caller to set a variable, and is still ours', () => {
    const missingKey =
      'No model configured to drive the app: set ANTHROPIC_API_KEY to let Reticle explore it for ' +
      'you. Without it, flows are recorded by your own coding agent through the MCP tools.';
    expect(recoveryFor(missingKey)).toBeDefined();
  });
});

describe('it does not swallow genuine failures', () => {
  /**
   * The whole point of `FEEDBACK_ASK`: an unanticipated failure is the highest-value moment to hear
   * from the agent. Broadening the authored-message rule must not silence that.
   */
  it('leaves an unanticipated failure unrecognized', () => {
    expect(recoveryFor('ECONNRESET while reading from the bridge socket')).toBeUndefined();
  });

  it('leaves a bare internal error unrecognized', () => {
    expect(
      recoveryFor('Cannot read properties of undefined (reading Symbol.iterator)'),
    ).toBeUndefined();
  });

  /**
   * A crash whose stack merely mentions our package is NOT a message we authored about arguments.
   * Keying on `reticle_` alone would capture it, which is why the rule wants a tool name or an
   * `args.` parameter in prose, not a path.
   */
  it('leaves a stack trace through our own files unrecognized', () => {
    expect(
      recoveryFor('TypeError at /node_modules/@reticlehq/server/dist/tools/act-tools.js:412:9'),
    ).toBeUndefined();
  });
});

/**
 * The guard the four previous patches did not leave behind.
 *
 * Each of them added one more spelling to `RULES` and a test pinning that one string, so the next
 * authored refusal defaulted to "unrecognized" again. This drives the real producer instead:
 * `resolveTargetRef` is pure, it is the function that writes both target-resolution refusals, and a
 * message it emits that `recoveryFor` does not know is the exact defect this file exists to prevent.
 *
 * Ambiguous-target was the fifth. Its text ends "pass an explicit `ref` from reticle_query.", and the
 * catch-all excludes a `reticle_*` name followed by `.` so that a module path in a stack trace stays
 * an unanticipated crash. A tool named at the end of a sentence looks exactly like one, so the
 * message fell through and told the caller their own underspecified selector might be a Reticle bug.
 */
describe('every refusal resolveTargetRef writes is recognized as ours', () => {
  const messageFor = (candidates: readonly unknown[]): string => {
    const resolution = resolveTargetRef(candidates);
    if ('error' !== resolution.kind) throw new Error('expected a refusal, got a ref');
    return resolution.message;
  };

  it('recognizes the no-match refusal', () => {
    expect(recoveryFor(messageFor([]))).toBeDefined();
  });

  it('recognizes the ambiguous-target refusal', () => {
    const message = messageFor([
      { ref: 'e1309', role: 'button', name: 'Send', visible: true },
      { ref: 'e1310', role: 'generic', visible: true },
    ]);
    expect(recoveryFor(message)).toBeDefined();
  });

  it('tells the caller the ambiguity is theirs to fix, not a defect to report', () => {
    const message = messageFor([
      { ref: 'e1', role: 'button', name: 'Send', visible: true },
      { ref: 'e2', role: 'link', name: 'Send', visible: true },
    ]);
    expect(recoveryFor(message)).toContain('not a Reticle defect');
  });

  /**
   * Deliberately NOT recognized. "matched an element with no usable ref" means the browser handed
   * back a candidate without one, which is a shape Reticle did not anticipate rather than anything
   * the caller can narrow. That is precisely the case the feedback ask exists for, so it keeps it.
   */
  it('leaves the unusable-ref refusal unrecognized, because that one may really be ours', () => {
    expect(recoveryFor(messageFor([{ role: 'button', visible: true }]))).toBeUndefined();
  });
});

import { describe, expect, it } from 'vitest';
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { TOOLS } from './tools.js';
import { REPO_ROOT } from '@/machine/repo-root.js';

const REPO = REPO_ROOT;
const DOCS = join(REPO, 'docs');

/**
 * `docs/` serves two audiences — users and contributors — and for a long time nothing recorded which
 * was which. Twenty-five files sat in one flat directory, six of them invisible to the docs site, and
 * the only way to find out where a page belonged was to open it.
 *
 * `docs/README.md` is the index that fixes that, and `docs/docs.json` is what the published site
 * actually reads. An index is worth exactly as much as its accuracy, and one maintained by discipline
 * is wrong within two months — so the rule is a red build rather than a convention, the same way
 * `integration-coverage.test.ts` holds `apps/`.
 *
 * Every direction below is a silent failure if it goes unchecked:
 *   - a page nobody indexed is a page no contributor finds;
 *   - a page missing from `docs.json` is one no user can reach;
 *   - a page `docs.json` lists but that does not exist is a 404 on the published site;
 *   - a page without frontmatter renders with its slug as the title and no search description.
 */

const INDEX = 'README.md';

/** The site's own landing page. Mintlify serves it at `/` implicitly, so it is never in the nav. */
const HOME = 'index.mdx';

/**
 * Not a page: the Agent Skill the docs host serves at `/skill.md` in place of one it would generate.
 * It is the canonical `SKILL.md` byte for byte (`init/src/skill-copies-agree.test.ts`), so its rules
 * are that file's, not this site's, and it is reached by URL rather than from the nav.
 */
const SKILL = 'skill.md';

const docsIndex = () => readFileSync(join(DOCS, INDEX), 'utf8');

/**
 * Directories under `docs/` that hold no site pages.
 *
 * `matrix/` is generated machine output plus its own README (`apps/e2e/matrix.mjs` writes it and the
 * file says so); the rest are assets. Everything else under `docs/` is a published page, including
 * the nested ones.
 */
const NON_PAGE_DIRS = new Set(['images', 'logo', 'favicon', 'matrix']);

/**
 * Every page, including the nested ones.
 *
 * This walked only the top level until the reference grew a page per CLI command and a page per
 * package. Those live in `docs/cli/` and `docs/packages/`, and a flat scan reported the two
 * DIRECTORIES as unpublished docs while every real page inside them went unchecked: the gate was
 * loudly wrong about two things and silently blind to thirty-four.
 */
const markdownPages = (dir = DOCS, prefix = ''): string[] => {
  const out: string[] = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const rel = `${prefix}${entry.name}`;
    if (entry.isDirectory()) {
      if (!NON_PAGE_DIRS.has(entry.name))
        out.push(...markdownPages(join(dir, entry.name), `${rel}/`));
      continue;
    }
    if (!entry.name.endsWith('.md') && !entry.name.endsWith('.mdx')) continue;
    if (rel === INDEX || rel === HOME || rel === SKILL) continue;
    out.push(rel);
  }
  return out;
};

/** Just the top-level pages: what `docs/README.md` is expected to list one by one. */
const topLevelPages = () => markdownPages().filter((f) => !f.includes('/'));

/** The page directories, which `docs/README.md` names as a group rather than row by row. */
const pageDirs = () => [
  ...new Set(
    markdownPages()
      .filter((f) => f.includes('/'))
      .map((f) => f.split('/')[0] ?? ''),
  ),
];

/** The file behind a nav slug, which may be authored as either `.md` or `.mdx`. */
const pageFile = (slug: string): string | null => {
  for (const ext of ['.md', '.mdx']) {
    const path = join(DOCS, `${slug}${ext}`);
    if (existsSync(path)) return path;
  }
  return null;
};

/** Slugs `docs.json` publishes, flattened out of the tab -> group -> pages nesting. */
const publishedSlugs = (): string[] => {
  const config: unknown = JSON.parse(readFileSync(join(DOCS, 'docs.json'), 'utf8'));
  const slugs: string[] = [];
  const walk = (node: unknown): void => {
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    if (null === node || 'object' !== typeof node) return;
    const record = node as Record<string, unknown>;
    if (Array.isArray(record.pages)) {
      for (const page of record.pages) {
        if ('string' === typeof page) slugs.push(page);
        else walk(page);
      }
    }
    Object.values(record).forEach(walk);
  };
  walk(config);
  return slugs;
};

describe('docs/README.md indexes every doc', () => {
  it('every top-level page is linked from the index', () => {
    const index = docsIndex();
    const unlisted = topLevelPages().filter((page) => !index.includes(`(${page})`));

    expect(
      unlisted,
      `These docs exist but are not in docs/README.md, so nobody will find them: ${unlisted.join(', ')}. ` +
        `Add each to the user table or the contributor table — the point of the index is that the ` +
        `two audiences are told apart.`,
    ).toEqual([]);
  });

  it('every page directory is named in the index', () => {
    // A row per page stops being useful once a directory holds one page per CLI command and one per
    // package: the index would be mostly index. The guarantee that matters (no page is unreachable)
    // belongs to the docs.json test below, which checks all of them individually. This one only has
    // to stop a whole directory going unmentioned to a human reading the repo.
    const index = docsIndex();
    const unmentioned = pageDirs().filter((dir) => !index.includes(`${dir}/`));

    expect(
      unmentioned,
      `These docs directories are not mentioned in docs/README.md: ${unmentioned.join(', ')}. ` +
        `Name the directory and say what is in it; the pages inside do not each need a row.`,
    ).toEqual([]);
  });
});

describe('docs/docs.json publishes every doc', () => {
  it('every page docs.json publishes actually exists', () => {
    const missing = publishedSlugs().filter((page) => null === pageFile(page));

    expect(
      missing,
      `docs.json publishes pages with no file behind them — each is a 404 on the docs site: ${missing.join(', ')}`,
    ).toEqual([]);
  });

  it('every markdown page under docs/ is published by docs.json', () => {
    const published = new Set(publishedSlugs());
    const orphans = markdownPages()
      .map((file) => file.replace(/\.mdx?$/, ''))
      .filter((slug) => !published.has(slug));

    expect(
      orphans,
      `These docs are not in any docs.json tab, so they are unreachable from the site navigation: ${orphans.join(', ')}. ` +
        `Add each to the tab it belongs in — Guides, Reference, or Contributing.`,
    ).toEqual([]);
  });

  it('every documented tool argument is one the tool actually accepts', () => {
    // Six argument bugs shipped on this branch before this gate existed: `name` for
    // `recordingName`, `name` for `flowName`, `name` for `baseline`, `testid` for `by`/`value`,
    // top-level `urlContains`/`status` for `mocks`, and `key` for `text`. Every one was written from
    // a neighbouring page or a plausible guess, and every one was caught only by calling the tool.
    //
    // Reticle refuses an unknown parameter rather than applying part of the call, so a reader who
    // copies one gets an error, not a wrong result. That is the good outcome and it still costs a
    // turn — and in a doc read by agents, a bad example is a bad example at scale.
    const allowed = new Map(
      TOOLS.map((tool) => [tool.name, new Set(Object.keys(tool.inputSchema))]),
    );

    /** Length of the object literal starting at `open`, so a scan cannot run into the next example. */
    const objectLength = (text: string, open: number): number => {
      let depth = 0;
      let inString = false;
      let escaped = false;
      for (let i = open; i < text.length; i++) {
        const ch = text[i] ?? '';
        if (inString) {
          if (escaped) escaped = false;
          else if ('\\' === ch) escaped = true;
          else if ('"' === ch) inString = false;
          continue;
        }
        if ('"' === ch) inString = true;
        else if ('{' === ch) depth++;
        else if ('}' === ch) {
          depth--;
          if (0 === depth) return i - open + 1;
        }
      }
      return text.length - open;
    };

    /** Top-level keys of the object literal starting at `open` (index of its `{`). */
    const topLevelKeys = (text: string, open: number): string[] => {
      const keys: string[] = [];
      let depth = 0;
      let inString = false;
      let escaped = false;
      let current = '';
      for (let i = open; i < text.length; i++) {
        const ch = text[i] ?? '';
        if (inString) {
          if (escaped) escaped = false;
          else if ('\\' === ch) escaped = true;
          else if ('"' === ch) {
            inString = false;
          } else if (1 === depth) current += ch;
          continue;
        }
        if ('"' === ch) {
          inString = true;
          if (1 === depth) current = '';
          continue;
        }
        if ('{' === ch || '[' === ch) depth++;
        else if ('}' === ch || ']' === ch) {
          depth--;
          if (0 === depth) break;
        } else if (':' === ch && 1 === depth && '' !== current) {
          keys.push(current);
          current = '';
        }
      }
      return keys;
    };

    const problems: string[] = [];
    for (const file of markdownPages()) {
      const text = readFileSync(join(DOCS, file), 'utf8');
      for (const match of text.matchAll(/"tool"\s*:\s*"(reticle_[a-z0-9_]+)"/g)) {
        const tool = match[1] ?? '';
        const names = allowed.get(tool);
        if (undefined === names) continue; // meta-tools and non-tools are covered by another check
        // Bound the search to the object that CONTAINS this "tool" key. Scanning forward without
        // that bound picks up the next example's args and blames them on this tool.
        const start = match.index ?? 0;
        let objectStart = -1;
        for (let i = start, depth = 0; i >= 0; i--) {
          const ch = text[i] ?? '';
          if ('}' === ch) depth++;
          else if ('{' === ch) {
            if (0 === depth) {
              objectStart = i;
              break;
            }
            depth--;
          }
        }
        if (0 > objectStart) continue;
        const object = text.slice(objectStart, objectStart + objectLength(text, objectStart));
        const argsAt = object.search(/"args"\s*:\s*\{/);
        if (0 > argsAt) continue; // this call takes no args
        const rest = object;
        const open = object.indexOf('{', argsAt + 6);
        for (const key of topLevelKeys(rest, open)) {
          if (!names.has(key)) {
            problems.push(
              `${file}: ${tool} does not accept "${key}" (accepts: ${[...names].join(', ')})`,
            );
          }
        }
      }
    }

    expect(
      problems,
      `These examples pass an argument the tool rejects. Reticle refuses the whole call rather than ` +
        `applying part of it, so a reader who copies one gets "NOT applied, so any result would be ` +
        `an answer to a different question": ${problems.join('; ')}`,
    ).toEqual([]);
  });

  it("a tool page's first example is a call that tool would accept", () => {
    // The `{ tool, args }` check above cannot see the direct form these pages use, where the
    // arguments stand alone under a heading naming the tool. The convention that makes it checkable:
    // in `tools-<x>.mdx`, the FIRST json block is the request. Every later block is a response.
    //
    // Without this, a typo in the headline example of a tool's own page is invisible — and that is
    // the example most likely to be copied.
    const allowed = new Map(
      TOOLS.map((tool) => [tool.name, new Set(Object.keys(tool.inputSchema))]),
    );

    const problems: string[] = [];
    let checked = 0;
    for (const file of markdownPages()) {
      if (!file.startsWith('tools/') || !file.endsWith('.mdx')) continue;
      const text = readFileSync(join(DOCS, file), 'utf8');

      // The tool this page documents, taken from its frontmatter title.
      const title = /^title:\s*(.+)$/m.exec(text)?.[1] ?? '';
      const named = [...title.matchAll(/reticle_[a-z0-9_]+/g)].map((m) => m[0]);
      // Pages covering more than one tool (or none) have no single subject to validate against.
      if (1 !== named.length) continue;
      const names = allowed.get(named[0] ?? '');
      if (undefined === names) continue;

      const block = /```json\n([\s\S]*?)```/.exec(text)?.[1] ?? '';
      let parsed: unknown;
      try {
        parsed = JSON.parse(block);
      } catch {
        continue; // multi-call or elided blocks are not a single request to check
      }
      if (null === parsed || 'object' !== typeof parsed || Array.isArray(parsed)) continue;

      checked += 1;
      for (const key of Object.keys(parsed)) {
        if (!names.has(key)) {
          problems.push(
            `${file}: the first example passes "${key}", which ${named[0] ?? ''} does not accept ` +
              `(accepts: ${[...names].join(', ')})`,
          );
        }
      }
    }

    // The denominator, and this guard is the reason to insist on one. The filter above read
    // `tools-` until the tool pages moved into `docs/tools/`, after which it matched no file at
    // all: `problems` was empty because nothing was examined, and an empty list of problems is
    // indistinguishable from a clean one. Counting what was actually validated is the only part
    // that can tell those two apart.
    expect(
      checked,
      'no tool page was validated — the page layout moved and this filter did not',
    ).toBeGreaterThan(10);

    expect(
      problems,
      `The headline example on a tool's own page is the one most likely to be copied, so it has to ` +
        `be a call that tool would accept: ${problems.join('; ')}`,
    ).toEqual([]);
  });

  it('the logo and favicon are readable against the theme they render on', () => {
    // Mintlify renders `logo.light` in LIGHT mode — the served HTML puts it in `block dark:hidden`.
    // Its own schema says the opposite ("the light version of the logo used in dark mode"), and
    // trusting that description shipped a white wordmark onto a white background and a black one onto
    // a dark background. Both were invisible, and nothing failed.
    //
    // So: the file behind `light` must be DARK ink, and the file behind `dark` must be LIGHT ink.
    const config: unknown = JSON.parse(readFileSync(join(DOCS, 'docs.json'), 'utf8'));
    const assets = config as { logo?: Record<string, string>; favicon?: Record<string, string> };

    /** Mean brightness of the fills in an SVG, 0 (black) to 255 (white). */
    const inkBrightness = (file: string): number | null => {
      const fills = readFileSync(join(DOCS, file), 'utf8').match(/fill="#([0-9A-Fa-f]{6})"/g) ?? [];
      const values = fills
        .map((fill) => /#([0-9A-Fa-f]{6})/.exec(fill)?.[1] ?? '')
        .filter((hex) => '' !== hex)
        .map((hex) => {
          const n = parseInt(hex, 16);
          return ((n >> 16) + ((n >> 8) & 0xff) + (n & 0xff)) / 3;
        });
      return 0 === values.length ? null : values.reduce((a, b) => a + b, 0) / values.length;
    };

    const problems: string[] = [];
    for (const [kind, pair] of [
      ['logo', assets.logo],
      ['favicon', assets.favicon],
    ] as const) {
      if (undefined === pair) continue;
      for (const [mode, expectation] of [
        ['light', 'dark ink for a light background'],
        ['dark', 'light ink for a dark background'],
      ] as const) {
        const file = pair[mode];
        if (undefined === file) continue;
        const brightness = inkBrightness(file);
        if (null === brightness) continue; // no explicit fills to judge
        const tooLight = 'light' === mode && brightness > 128;
        const tooDark = 'dark' === mode && brightness < 128;
        if (tooLight || tooDark) {
          problems.push(
            `${kind}.${mode} is ${file} with ink brightness ${Math.round(brightness)} — ${mode} ` +
              `mode needs ${expectation}, so this renders invisible`,
          );
        }
      }
    }

    expect(
      problems,
      `A logo the same colour as the page behind it is not a rendering bug anyone notices in a diff: ` +
        `${problems.join('; ')}`,
    ).toEqual([]);
  });

  it('no page contains markup MDX will refuse to build', () => {
    // Two pages 404'd on the deployed site while passing every check here: they existed, were in the
    // nav, had frontmatter, and their links resolved. Mintlify compiles markdown as MDX, so `<1s` in
    // a table cell is read as a JSX tag and `{action:"review"}` as a JS expression. The page fails to
    // build and simply is not there.
    //
    // Nothing local caught it because the file is perfectly good markdown. Only fetching the built
    // site did. These are the two shapes that actually broke.
    const HAZARDS: { pattern: RegExp; what: string }[] = [
      {
        pattern: /<[0-9]/,
        what: 'a bare `<` before a digit (MDX reads it as a tag) — wrap it in backticks',
      },
      {
        pattern: /\]\([^)]*[{}][^)]*\)/,
        what: 'a link whose URL contains { or } (MDX reads it as an expression)',
      },
      { pattern: /\]\([^)\s]*\s[^)]*\)/, what: 'a link whose URL contains a space' },
    ];

    const problems: string[] = [];
    for (const file of markdownPages()) {
      const source = readFileSync(join(DOCS, file), 'utf8');
      // Fenced and inline code are safe: MDX does not parse inside them.
      const prose = source.replace(/```[\s\S]*?```/g, '').replace(/`[^`\n]*`/g, '');
      for (const line of prose.split('\n')) {
        for (const { pattern, what } of HAZARDS) {
          if (pattern.test(line)) problems.push(`${file}: ${what} — ${line.trim().slice(0, 70)}`);
        }
      }
    }

    expect(
      problems,
      `MDX will not build these, and a page that fails to build is a 404 on the site with nothing ` +
        `failing here: ${problems.join('; ')}`,
    ).toEqual([]);
  });

  it('no page shows a predicate combinator in a shape that does not parse', () => {
    // `{ allOf: [ … ] }` reads perfectly and is rejected by the schema. Reticle refuses the whole
    // call rather than evaluating part of it, so a reader who copies one gets NO verdict, which is
    // strictly worse than a failing one. Eight of these shipped across the docs before a sweep.
    // The correct shape is `{ kind: "allOf", predicates: [ … ] }`.
    const BARE = /(?:"(?:allOf|anyOf)"|\b(?:allOf|anyOf))\s*:\s*\[/;
    // Lines that deliberately show the wrong shape, near a marker saying so.
    const DISCLAIMER = /WRONG|does not parse|do(?:es)? not parse|neither does/i;

    const offenders: string[] = [];
    for (const file of markdownPages()) {
      const lines = readFileSync(join(DOCS, file), 'utf8').split('\n');
      lines.forEach((line, i) => {
        if (!BARE.test(line)) return;
        if (/"?kind"?\s*:\s*"(?:allOf|anyOf)"[\s\S]*?"?predicates"?\s*:/.test(line)) return;
        const context = lines.slice(Math.max(0, i - 4), i + 2).join('\n');
        if (DISCLAIMER.test(context)) return;
        offenders.push(`${file}:${String(i + 1)}`);
      });
    }

    expect(
      offenders,
      `A combinator needs its own kind and a \`predicates\` array: ` +
        `{ kind: "allOf", predicates: [ … ] }. The bare form does not parse, and Reticle returns no ` +
        `verdict at all rather than a failing one: ${offenders.join(', ')}`,
    ).toEqual([]);
  });

  it('every reticle_* tool the docs name still exists in the source', () => {
    // A tool rename once left four e2e specs dead across a whole framework and nothing caught it.
    // The docs are the same shape of victim: they name 50-odd tools, and a rename turns each mention
    // into a lie that renders perfectly. Nothing throws, no test reddens, and an agent following the
    // page calls a tool that is not there.
    const TOOL = /\breticle_[a-z0-9_]+\b/g;

    const sourceNames = new Set<string>();
    const walk = (dir: string): void => {
      for (const entry of readdirSync(dir, { withFileTypes: true })) {
        const full = join(dir, entry.name);
        if (entry.isDirectory()) walk(full);
        else if (entry.name.endsWith('.ts')) {
          for (const name of readFileSync(full, 'utf8').match(TOOL) ?? []) sourceNames.add(name);
        }
      }
    };
    walk(join(REPO, 'server', 'src'));
    walk(join(REPO, 'core', 'src'));
    // `init` too. It EMITS `reticle_*` identifiers into the files it generates -- the Django
    // middleware module is `reticle_dev.py` -- and a docs page quoting what `init` prints was
    // reported here as naming a tool that does not exist. The name does exist; this walk did not
    // reach the package that owns it, which made the guard fire on a page that was correct.
    walk(join(REPO, 'init', 'src'));

    const unknown: string[] = [];
    for (const file of markdownPages()) {
      const mentioned = new Set(readFileSync(join(DOCS, file), 'utf8').match(TOOL) ?? []);
      for (const name of mentioned) {
        if (!sourceNames.has(name)) unknown.push(`${file} -> ${name}`);
      }
    }

    expect(
      unknown,
      `These pages name a reticle_* tool that does not exist in the source. Either the tool was ` +
        `renamed and the docs were not, or the page has a typo — both render perfectly and both send ` +
        `an agent to call something that is not there: ${unknown.join('; ')}`,
    ).toEqual([]);
  });

  it('MDX components appear only in .mdx pages', () => {
    // Whether Mintlify renders JSX inside a plain `.md` file is not something this repo has
    // verified, and the failure mode if it does not is silent: the component renders as literal
    // text in the middle of a paragraph. Keep components where they are known to work.
    const COMPONENT =
      /<(Note|Tip|Warning|Info|Card|CardGroup|Columns|Accordion|AccordionGroup|Steps|Step|Frame|Tabs|Tab)\b/;
    const offenders = markdownPages()
      .filter((file) => file.endsWith('.md'))
      .filter((file) => COMPONENT.test(readFileSync(join(DOCS, file), 'utf8')));

    expect(
      offenders,
      `These .md pages use MDX components. Either rename the page to .mdx, or use plain markdown ` +
        `(a blockquote reads fine and cannot fail): ${offenders.join(', ')}`,
    ).toEqual([]);
  });

  it('no frontmatter value contains an unquoted colon', () => {
    // This one took two pages off the live site while every check in this repo stayed green.
    // A plain (unquoted, unbracketed) YAML scalar cannot contain `: `, so a description reading
    //   description: Diagnose the setup in one command: Chromium, daemon, ...
    // is a parse error. Mintlify does not build the page and serves a 404, while the file is
    // present, listed in docs.json, and indexed in README.md. Nothing above can see it, because
    // in the repository everything is consistent; the damage is only on the deployed site.
    const offenders: string[] = [];
    for (const file of markdownPages()) {
      const text = readFileSync(join(DOCS, file), 'utf8');
      if (!text.startsWith('---\n')) continue;
      const end = text.indexOf('\n---', 4);
      if (-1 === end) continue;
      for (const line of text.slice(4, end).split('\n')) {
        const match = /^([A-Za-z][\w-]*):\s+(.*)$/.exec(line);
        if (null === match) continue;
        const key = match[1];
        const value = match[2];
        if (undefined === value || '' === value) continue;
        // Already a quoted, flow or block scalar: YAML handles the colon fine.
        if ('\'"[{|>'.includes(value.slice(0, 1))) continue;
        if (value.includes(': ')) offenders.push(`${file}: ${key}`);
      }
    }

    expect(
      offenders,
      `These frontmatter values contain an unquoted colon, which is invalid YAML and 404s the page ` +
        `on the published site while everything in the repo still looks correct. Wrap the value in ` +
        `single quotes: ${offenders.join(', ')}`,
    ).toEqual([]);
  });

  it('no page uses an em dash', () => {
    // House style for the published docs. Nothing else enforces it, and a rule enforced by review
    // is a rule that is wrong within a month. Use a comma, a colon, a full stop, or a rewrite.
    const offenders = markdownPages()
      .map((file) => ({
        file,
        count: (readFileSync(join(DOCS, file), 'utf8').match(/—/g) ?? []).length,
      }))
      .filter((row) => row.count > 0)
      .map((row) => `${row.file} (${row.count})`);

    expect(
      offenders,
      `These pages use em dashes. Replace each with a comma, a colon, a full stop, or a rewrite: ` +
        `${offenders.join(', ')}`,
    ).toEqual([]);
  });

  it('no page draws a diagram out of box-drawing characters', () => {
    // Box-drawing and arrow glyphs. ASCII diagrams were ruled out for the published docs: they
    // wrap badly on narrow screens, are unreadable to a screen reader, and read as unfinished.
    // Mermaid renders natively on Mintlify and is the replacement.
    const ART = /[─-╿▲▼◄►]/;
    const offenders = markdownPages().filter((file) =>
      ART.test(readFileSync(join(DOCS, file), 'utf8')),
    );

    expect(
      offenders,
      `These pages contain box-drawing characters. Use a \`\`\`mermaid block instead — it renders as a ` +
        `real diagram: ${offenders.join(', ')}`,
    ).toEqual([]);
  });

  it('every internal link resolves to a page or an image that exists', () => {
    const slugs = new Set(markdownPages().map((file) => file.replace(/\.mdx?$/, '')));
    const broken: string[] = [];

    for (const file of markdownPages()) {
      const source = readFileSync(join(DOCS, file), 'utf8');
      const links = [
        ...source.matchAll(/href="(\/[^"#]*)"/g),
        ...source.matchAll(/\]\((\/[^)#]*)\)/g),
      ].map((match) => match[1] ?? '');

      for (const link of new Set(links)) {
        if (link.startsWith('/images/')) {
          if (!existsSync(join(DOCS, link))) broken.push(`${file} -> ${link} (missing image)`);
          continue;
        }
        const slug = link.replace(/^\/|\/$/g, '');
        if ('' !== slug && !slugs.has(slug)) broken.push(`${file} -> ${link} (no such page)`);
      }
    }

    expect(
      broken,
      `These links 404 on the published site. A dead link in docs is silent — nothing throws, the ` +
        `page renders, and the reader hits a wall: ${broken.join('; ')}`,
    ).toEqual([]);
  });

  it('every published page carries frontmatter and no duplicate H1', () => {
    const broken = publishedSlugs()
      .map((slug) => ({ slug, file: pageFile(slug) }))
      .filter((page): page is { slug: string; file: string } => null !== page.file)
      .map(({ slug, file }) => {
        // Windows checkouts carry CRLF, which makes every `^---$` and `startsWith('---\n')`
        // below miss and reports all 24 pages as unfrontmattered. Normalise before parsing.
        const source = readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
        const [, frontmatter = '', body = ''] = source.split(/^---$/m);
        if (!source.startsWith('---\n')) return `${slug}: no frontmatter block`;
        if (!/^title:\s*\S/m.test(frontmatter)) return `${slug}: frontmatter has no title`;
        if (!/^description:\s*\S/m.test(frontmatter))
          return `${slug}: frontmatter has no description`;
        // A `# ` inside a fenced block is a shell comment, not a heading.
        const prose = body.replace(/^```[\s\S]*?^```/gm, '');
        if (/^# /m.test(prose)) return `${slug}: body still has an H1, which renders twice`;
        return null;
      })
      .filter((problem): problem is string => null !== problem);

    expect(
      broken,
      `Mintlify renders the frontmatter title as the page heading and the description as the search ` +
        `snippet, so a page without them ships with its slug as its name: ${broken.join('; ')}`,
    ).toEqual([]);
  });
});

/**
 * From a persona drive: a typed password reached the local session journal in clear — a `dom.attr`
 * event with `{ attr: "value", value: "<password>" }` on the `type=password` input, because the DOM
 * observer redacted nothing while the field observer beside it already knew the field was secret.
 */
import { describe, it, expect } from 'vitest';
import { EventType, REDACTED_VALUE } from '@reticlehq/core';
import { installDom } from './dom.js';

async function flushMutations(): Promise<void> {
  await Promise.resolve();
  await new Promise<void>((resolve) => setTimeout(resolve, 0));
}

const TYPED = 'hunter2-correct-horse';

async function attrEventsAfter(html: string, change: (el: Element) => void) {
  document.body.innerHTML = html;
  const el = document.querySelector('input, textarea') as Element;
  const events: { type: EventType; data: Record<string, unknown> }[] = [];
  const teardown = installDom((type, data) => events.push({ type, data }));
  change(el);
  await flushMutations();
  teardown();
  return events;
}

describe('a secret field, seen by the DOM observer', () => {
  it('never carries a password input’s value, old or new', async () => {
    const events = await attrEventsAfter('<input type="password" value="old-secret">', (el) =>
      el.setAttribute('value', TYPED),
    );
    expect(JSON.stringify(events)).not.toContain(TYPED);
    expect(JSON.stringify(events)).not.toContain('old-secret');
    const attr = events.find((e) => e.type === EventType.DOM_ATTR);
    expect(attr?.data['value']).toBe(REDACTED_VALUE);
  });

  it('redacts a field named as a secret (one-time code, card number) the same way', async () => {
    const events = await attrEventsAfter('<input name="otp" autocomplete="one-time-code">', (el) =>
      el.setAttribute('value', TYPED),
    );
    expect(JSON.stringify(events)).not.toContain(TYPED);
  });

  it('never carries a secret textarea’s text, however it is set', async () => {
    const events = await attrEventsAfter('<textarea name="password"></textarea>', (el) => {
      el.textContent = TYPED;
    });
    expect(JSON.stringify(events)).not.toContain(TYPED);
  });

  it('still reports an ordinary field’s value', async () => {
    const events = await attrEventsAfter('<input name="email">', (el) =>
      el.setAttribute('value', 'ada@example.com'),
    );
    expect(events.find((e) => e.type === EventType.DOM_ATTR)?.data['value']).toBe(
      'ada@example.com',
    );
  });
});

/**
 * A rewrite of the same bytes is not a change, and must not reach the buffer.
 *
 * A field app rewrote one UI key thousands of times a minute with byte-identical content. Those
 * no-op writes filled the ring buffer — `held: 2000, dropped: 70482` — and the verdict taken in that
 * window reported `net.total: 0` and "state never changed" while the POST carrying the actual root
 * cause was on the wire. The agent nearly shipped "clicking Accept fires no network request" as a
 * diagnosis. The buffer starvation is the cause; a diff whose `old` equals its `new` is the fuel.
 */
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { EventType } from '@reticlehq/core';
import { installStorage } from './storage.js';

describe('a storage write that changes nothing emits nothing', () => {
  let events: Array<{ type: EventType; data: Record<string, unknown> }>;
  let teardown: () => void;

  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
    events = [];
    teardown = installStorage((type, data) => events.push({ type, data }));
  });
  afterEach(() => {
    teardown();
    localStorage.clear();
    sessionStorage.clear();
  });

  const changes = (): number => events.filter((e) => e.type === EventType.STORAGE_CHANGE).length;

  it('does not emit when the same value is written back', () => {
    localStorage.setItem('ui', '{"panel":"mesh"}');
    expect(changes(), 'the first write is a real change').toBe(1);
    for (let i = 0; i < 500; i += 1) localStorage.setItem('ui', '{"panel":"mesh"}');
    expect(changes(), '500 identical rewrites carry no information and must cost no buffer').toBe(
      1,
    );
  });

  it('still emits when the value actually changes', () => {
    localStorage.setItem('ui', 'a');
    localStorage.setItem('ui', 'a');
    localStorage.setItem('ui', 'b');
    expect(changes()).toBe(2);
    expect(events.at(-1)?.data).toMatchObject({ key: 'ui', old: 'a', new: 'b' });
  });

  it('emits the first write of a key that was absent', () => {
    localStorage.setItem('fresh', '');
    expect(changes(), 'absent is not the empty string').toBe(1);
  });

  it('the app still holds the value it wrote, emitted or not', () => {
    localStorage.setItem('ui', 'x');
    localStorage.setItem('ui', 'x');
    expect(localStorage.getItem('ui')).toBe('x');
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { installStorage, readStorage, type StorageSnapshot } from './storage.js';

describe('readStorage', () => {
  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
  });

  it('reads local + session and redacts sensitive keys', () => {
    const tokenValue = '<REDACTED>';
    localStorage.setItem('cart', '3-items');
    localStorage.setItem('auth_token', tokenValue); // sensitive key → redacted
    sessionStorage.setItem('view', 'overview');
    const snap = readStorage() as StorageSnapshot;
    expect(snap.local['cart']).toBe('3-items');
    expect(snap.local['auth_token']).toBe('[REDACTED]');
    expect(snap.local['auth_token']).not.toBe(tokenValue);
    expect(snap.session['view']).toBe('overview');
  });

  it('scopes to a single area (local, session, cookies)', () => {
    localStorage.setItem('k', 'v');
    sessionStorage.setItem('s', 'w');
    document.cookie = 'scopecookie=present';
    expect(readStorage('local')).toEqual({ k: 'v' });
    expect(readStorage('session')).toEqual({ s: 'w' });
    expect(readStorage('cookies')).toMatchObject({ scopecookie: 'present' });
  });

  it('reads cookies, redacts sensitive cookie names, and url-decodes values', () => {
    const cookieVal = 'sess-xyz-abcdef123';
    document.cookie = 'theme=dark';
    document.cookie = 'greeting=hello%20world';
    document.cookie = `session_token=<REDACTED> // sensitive → redacted
    const cookies = readStorage('cookies') as Record<string, string>;
    expect(cookies['theme']).toBe('dark');
    expect(cookies['greeting']).toBe('hello world'); // decodeURIComponent applied
    expect(cookies['session_token']).toBe('[REDACTED]');
    expect(cookies['session_token']).not.toBe(cookieVal);
  });

  it('a throwing storage area returns {} instead of crashing the whole read', () => {
    const realLocal = Object.getOwnPropertyDescriptor(window, 'localStorage');
    Object.defineProperty(window, 'localStorage', {
      configurable: true,
      get() {
        throw new Error('SecurityError: storage disabled');
      },
    });
    try {
      const snap = readStorage() as StorageSnapshot;
      expect(snap.local).toEqual({}); // caught, empty — session + cookies still read
      expect(snap).toHaveProperty('session');
      expect(snap).toHaveProperty('cookies');
    } finally {
      if (realLocal) Object.defineProperty(window, 'localStorage', realLocal);
    }
  });

  it('redacts secret-shaped values (e.g. JWT) even under benign key names', () => {
    const jwtSecret =
      '<REDACTED>';
    const apiKeySecret = '<REDACTED>';

    localStorage.setItem('custom_app_cache', jwtSecret);
    sessionStorage.setItem('cached_payload', `prefix-${apiKeySecret}-suffix`);
    document.cookie = `benign_cookie=${jwtSecret}`;

    const snap = readStorage() as StorageSnapshot;
    expect(snap.local['custom_app_cache']).toBe('[REDACTED]');
    expect(snap.local['custom_app_cache']).not.toContain(jwtSecret);

    expect(snap.session['cached_payload']).toBe('prefix-[REDACTED]-suffix');
    expect(snap.session['cached_payload']).not.toContain(apiKeySecret);

    expect(snap.cookies['benign_cookie']).toBe('[REDACTED]');
    expect(snap.cookies['benign_cookie']).not.toContain(jwtSecret);
  });

  it('preserves legitimate near-miss values that merely resemble a secret', () => {
    const nearMiss1 = 'eyJshort'; // not a 3-part base64 JWT
    const nearMiss2 = 'sk_unknown_prefix_12345'; // not live/test
    const legitimateText = 'standard-user-profile-description';
    const validJson = JSON.stringify({ count: 42, label: 'items_in_cart' });

    localStorage.setItem('description', legitimateText);
    localStorage.setItem('cart_json', validJson);
    localStorage.setItem('near_miss_data', nearMiss1);
    sessionStorage.setItem('fake_key', nearMiss2);

    const snap = readStorage() as StorageSnapshot;
    expect(snap.local['description']).toBe(legitimateText);
    expect(snap.local['cart_json']).toBe(validJson);
    expect(snap.local['near_miss_data']).toBe(nearMiss1);
    expect(snap.session['fake_key']).toBe(nearMiss2);
  });
});

/**
 * A throwing observation must never escape into the app.
 *
 * The patched `setItem` builds its payload INSIDE the app's call stack — reading the old value,
 * resolving the area, redacting. Guarding only the transport hop left all of that exposed, so a throw
 * there surfaced as an exception from `localStorage.setItem` AFTER the write had already succeeded.
 * The app sees a failure that did not happen, caused entirely by the observability SDK.
 */
describe('a failing observation cannot break the host app', () => {
  it('setItem still succeeds and still writes when emit throws', () => {
    const teardown = installStorage(() => {
      throw new Error('observer blew up');
    });
    try {
      expect(() => localStorage.setItem('k', 'v')).not.toThrow();
      expect(localStorage.getItem('k')).toBe('v');
    } finally {
      teardown();
      localStorage.removeItem('k');
    }
  });

  it('removeItem still succeeds and still removes when emit throws', () => {
    localStorage.setItem('gone', 'x');
    const teardown = installStorage(() => {
      throw new Error('observer blew up');
    });
    try {
      expect(() => localStorage.removeItem('gone')).not.toThrow();
      expect(localStorage.getItem('gone')).toBeNull();
    } finally {
      teardown();
    }
  });
});

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { EventType } from '@reticlehq/core';
import { installStorage } from './storage.js';
import { ReticleStorageKey, TOUR_SEEN_KEY_PREFIX } from '@/storage-keys.js';

interface Captured {
  type: EventType;
  data: Record<string, unknown>;
}

describe('installStorage — storage write events', () => {
  let events: Captured[];
  let teardown: () => void;

  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
    events = [];
    teardown = installStorage((type, data) => events.push({ type, data }));
  });
  afterEach(() => {
    teardown();
    localStorage.clear();
    sessionStorage.clear();
  });

  it('emits a STORAGE_CHANGE with old + new on setItem', () => {
    localStorage.setItem('cart', '2-items');
    localStorage.setItem('cart', '3-items');
    const changes = events.filter((e) => e.type === EventType.STORAGE_CHANGE);
    expect(changes).toHaveLength(2);
    expect(changes[1]?.data).toMatchObject({
      area: 'local',
      key: 'cart',
      old: '2-items',
      new: '3-items',
    });
  });

  /*
   * The HUD's own writes are not the app's. `reticle-presenter-log` showed up in a verdict's
   * `storageKeysChanged` as if the app had changed it, and so would every other key the SDK keeps.
   */
  it("never reports Reticle's own keys as the app's storage changes", () => {
    for (const key of Object.values(ReticleStorageKey)) {
      sessionStorage.setItem(key, '1');
      localStorage.setItem(key, '1');
      localStorage.removeItem(key);
    }
    localStorage.setItem(`${TOUR_SEEN_KEY_PREFIX}web`, '1');
    sessionStorage.clear();
    localStorage.setItem('reticle.bench.authToken', 'app-owned');
    const keys = events
      .filter((e) => e.type === EventType.STORAGE_CHANGE)
      .map((e) => e.data['key']);
    expect(keys, "an app key that merely starts with reticle. is still the app's").toEqual([
      'reticle.bench.authToken',
    ]);
  });

  it('redacts the value of a credential-bearing key', () => {
    localStorage.setItem('auth_token', 'tok-secret-123');
    const change = events.find((e) => e.type === EventType.STORAGE_CHANGE);
    expect(change?.data['new']).toBe('[REDACTED]');
    expect(change?.data['new']).not.toContain('secret');
  });

  it('distinguishes session from local by the storage instance', () => {
    sessionStorage.setItem('view', 'overview');
    expect(events[0]?.data['area']).toBe('session');
  });

  it('emits a change with no `new` field on removeItem (signals removal)', () => {
    localStorage.setItem('k', 'v');
    events.length = 0;
    localStorage.removeItem('k');
    const change = events.find((e) => e.type === EventType.STORAGE_CHANGE);
    expect(change?.data).toMatchObject({ area: 'local', key: 'k', old: 'v' });
    expect(change?.data['new']).toBeUndefined();
  });

  it('stops emitting after teardown (fully reversible)', () => {
    teardown();
    events.length = 0;
    localStorage.setItem('after', 'x');
    expect(events).toHaveLength(0);
  });

  it('emits a removal per key on clear() — the common logout path', () => {
    // localStorage.clear() is how most apps log out; it used to emit NOTHING, so "logout cleared the
    // session" was unverifiable from the write path.
    localStorage.setItem('a', '1');
    localStorage.setItem('auth_token', 'tok-secret-123');
    events.length = 0;
    localStorage.clear();
    const changes = events.filter((e) => e.type === EventType.STORAGE_CHANGE);
    expect(changes).toHaveLength(2);
    for (const c of changes) {
      expect(c.data['area']).toBe('local');
      expect(c.data['new']).toBeUndefined(); // removal
    }
    const authChange = changes.find((c) => 'auth_token' === c.data['key']);
    expect(authChange?.data['old']).toBe('[REDACTED]'); // credential redacted, not leaked on clear
    expect(localStorage.length).toBe(0); // the app's clear still happened
  });

  it('restores clear() on teardown (fully reversible)', () => {
    teardown();
    events.length = 0;
    localStorage.setItem('k', 'v');
    localStorage.clear();
    expect(events).toHaveLength(0);
    expect(localStorage.length).toBe(0);
  });
});

/**
 * The dev-server policy is written once and quoted twice, so the copy has to be checked.
 *
 * `DEV_SERVER_POLICY` in `agent-rules.ts` is the source: it is what `init` writes into the user's
 * CLAUDE.md / AGENTS.md, and it is the text an agent re-reads every turn. Four of its nine
 * sentences are ALSO typed by hand into the agent-facing guidance (`SKILL.md` and its setup
 * companion `docs/skill-setup.md`), which an agent reads at setup.
 *
 * Two copies of the same instruction with no link between them drift in the direction that is
 * hardest to notice: the constant gets corrected after a field report, and the hand-typed copy
 * keeps telling the older story to every new reader. That is the failure this repo has already
 * had with tool names, surface counts and the "four rules" preamble.
 *
 * The right end state is generation — SKILL.md rendered from the constants it quotes. That is a
 * build step this repo does not have yet, so the next best thing is a guard: if the source moves
 * and the copy does not, this goes red and somebody decides which one is right.
 *
 * Deliberately checks a PREFIX of each sentence rather than the whole file. The two documents are
 * allowed to differ in framing and length; what they may not do is state the same rule in two
 * different ways.
 */

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { DEV_SERVER_POLICY } from './project/agent-rules.js';
import { execFileSync } from 'node:child_process';

// Asked rather than counted. A walk of `..` segments up to the repository is a statement about how
// deeply this package sits, not about the repository, and packages move -- when one did, every such
// walk quietly started reading a directory that does not exist.
const REPO = execFileSync('git', ['rev-parse', '--show-toplevel'], {
  cwd: import.meta.dirname,
  encoding: 'utf8',
}).trim();

/**
 * The agent-facing guidance, as one body of text.
 *
 * The dev-server rules used to sit in `SKILL.md`. They now live in `docs/skill-setup.md`, because
 * they are setup-time instructions and an agent that is already running should not pay to read them
 * every session. What matters to this guard is unchanged: the rules are quoted SOMEWHERE an agent
 * reads, and that copy must not drift from the constant. So both files are checked together, and
 * moving a rule between them stays a non-event.
 */
const skill = [
  readFileSync(join(REPO, 'SKILL.md'), 'utf8'),
  readFileSync(join(REPO, 'docs', 'skill-setup.md'), 'utf8'),
].join('\n');

/** Sentences long enough to be a rule rather than a connective. */
const sentences = DEV_SERVER_POLICY.split(/\.\s+/)
  .map((s) => s.replace(/\\`/g, '`').trim())
  .filter((s) => s.length > 50);

/** The prefix length that identifies a sentence without demanding the whole of it. */
const KEY = 60;

/**
 * How many policy rules SKILL.md quotes. Pinned so drift cannot shrink the checked set.
 *
 * Was 4. Rose to 11 when the restart branch was promoted from an aside to the head of the policy:
 * the two documents had been stating the same rule in two different ways, this guard caught it, and
 * the fix was to make the constant carry SKILL.md's corrected wording rather than to loosen the
 * check. A higher number is a tighter guard — every additional sentence is one more rule that can no
 * longer drift silently.
 *
 * Briefly 12, when `init` gained the ability to start the dev server itself. It went back to 11
 * because the every-turn budget refused the extra sentence, and the refusal was right: that `init`
 * may start a dev server is SETUP-time information, and this constant is the text an agent re-reads
 * on every turn to decide what to do while working. It lives in SKILL.md instead, which is read
 * once, at the moment it applies.
 */
const QUOTED_TODAY = 11;

describe('the dev-server policy has one source', () => {
  it('the constant still carries the rules, so this guard cannot go vacuous', () => {
    expect(sentences.length).toBeGreaterThan(5);
  });

  /**
   * The COUNT is pinned, not just the matches.
   *
   * The first version of this test asked only that the sentences SKILL.md currently quotes still
   * match. That is vacuous by construction: change the constant and the sentence simply stops
   * being "currently quoted", so it drops out of the set and the test passes greener than before.
   * Verified by doing exactly that — reword one rule in the constant, and a guard written to catch
   * precisely that stayed green.
   *
   * Pinning the number means drift in either direction is visible: reword the constant without
   * SKILL.md and the count falls; drop a quote from SKILL.md and it falls too. A deliberate change
   * to either updates this number and says so in the diff.
   */
  it('SKILL.md still quotes the same rules, word for word', () => {
    const quoted = sentences.filter((s) => skill.includes(s.slice(0, KEY)));
    expect(
      quoted.length,
      'SKILL.md and DEV_SERVER_POLICY have drifted: a rule was reworded in one and not the other. ' +
        'Decide which is right, fix the other, and update this count.',
    ).toBe(QUOTED_TODAY);
  });
});

import { afterEach, describe, expect, it } from 'vitest';
import * as http from 'node:http';
import type { AddressInfo } from 'node:net';
import { WebSocket } from 'ws';
import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import {
  AGENT_STOPPED_NOTICE,
  RETICLE_WS_PATH,
  ReticleCommand,
  MessageKind,
  SessionState,
} from '@reticlehq/core';
import { MCP_SSE_PATH } from '@reticlehq/core';
import { createSharedServer, type SharedServer } from './surface/http-server.js';
import { Bridge } from './portal/bridge/bridge.js';
import { endAllSessions } from './portal/session/session-reaper.js';

/**
 * End-to-end proof of the agent-independent presence chain through the REAL wiring:
 * agent's SSE drops → SharedServer presence(false) → endAllSessions → Session.autoEnd →
 * PRESENTER push over the WS bridge → the browser panel.
 * No mocks in the path: a real Bridge, a real Session, a real WebSocket browser stand-in.
 */

let shared: SharedServer | undefined;
let bridge: Bridge | undefined;
/** Every presence transition the stack reported, so a test can wait for one instead of guessing. */
let presence: boolean[] = [];

afterEach(async () => {
  await bridge?.close();
  await shared?.close();
  shared = undefined;
  bridge = undefined;
  presence = [];
});

/** Replicates the three lines of production wiring in index.ts (startDaemon). Returns the bound port. */
async function startStack(): Promise<number> {
  shared = createSharedServer();
  shared.attachMcp(fakeMcpServer);
  const srv = shared.httpServer;
  bridge = new Bridge({ port: 0, server: srv });
  const b = bridge;
  shared.attachAgentPresence((connected) => {
    presence.push(connected);
    if (!connected) endAllSessions(b.sessions, AGENT_STOPPED_NOTICE);
  });
  await new Promise<void>((resolve) => srv.listen(0, '127.0.0.1', resolve));
  return (srv.address() as AddressInfo).port;
}

/** A no-op McpServer that starts its transport so the SSE response headers flush. */
function fakeMcpServer(): McpServer {
  return {
    connect: (transport: { start: () => Promise<void> }) => transport.start(),
    close: () => Promise.resolve(),
  } as unknown as McpServer;
}

/** Minimal browser SDK stand-in: HELLOs to register a session, records the commands it receives. */
class FakeBrowser {
  readonly received: { name: string; args: Record<string, unknown> }[] = [];
  readonly #ws: WebSocket;
  constructor(
    port: number,
    private readonly sessionId: string,
  ) {
    const host = '127.0.0.1';
    this.#ws = new WebSocket(`ws://${host}:${String(port)}${RETICLE_WS_PATH}`, {
      origin: 'http://localhost',
    });
  }
  open(): Promise<void> {
    return new Promise((resolve) => {
      this.#ws.on('open', () => {
        this.#ws.send(
          JSON.stringify({
            kind: MessageKind.HELLO,
            protocolVersion: 1,
            sessionId: this.sessionId,
            url: 'http://localhost:3000/checkout',
            title: 'Checkout',
            adapters: [],
            hasCapabilities: false,
          }),
        );
        this.#ws.on('message', (raw) => {
          const msg = JSON.parse((raw as Buffer).toString('utf8')) as Record<string, unknown>;
          if (msg['kind'] === MessageKind.COMMAND) {
            this.received.push({
              name: msg['name'] as string,
              args: (msg['args'] ?? {}) as Record<string, unknown>,
            });
          }
        });
        resolve();
      });
    });
  }
  close(): void {
    this.#ws.close();
  }
}

function openSse(port: number): Promise<http.ClientRequest> {
  return new Promise((resolve) => {
    const req = http.get({ host: '127.0.0.1', port, path: MCP_SSE_PATH, agent: false }, () =>
      resolve(req),
    );
    req.on('error', () => undefined);
  });
}

/**
 * Wait until `condition` holds, polling, instead of sleeping a fixed number of milliseconds and
 * hoping.
 *
 * This file used to pause a flat 60ms between every step. Sixty milliseconds is a statement about the
 * machine, not about the system under test, so it passed on a developer laptop and failed on a loaded
 * CI runner — the flake mode this repo already knows about and writes down in CLAUDE.md.
 *
 * The specific failure: the pause after `openSse` was standing in for "the server has registered the
 * agent as present". When it had not, `agent.destroy()` produced no true->false transition, so
 * `endAllSessions` never ran, no PRESENTER command was pushed, and the assertion failed with the
 * uninformative `expected undefined to be defined`.
 *
 * A generous timeout costs nothing when the condition is already true, which is the normal case. It
 * is deliberately BELOW vitest's own 5s test timeout: at 5s vitest's timeout fired first and the
 * failure read `Test timed out in 5000ms`, which says nothing about which step never happened.
 */
async function waitFor(condition: () => boolean, what: string, timeoutMs = 3_000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (!condition()) {
    if (Date.now() > deadline) {
      throw new Error(`timed out after ${String(timeoutMs)}ms waiting for ${what}`);
    }
    await new Promise((r) => setTimeout(r, 5));
  }
}

/**
 * A fixed pause, used ONLY to assert that something did NOT happen. You cannot poll for the absence
 * of an event, so a negative check has to give the system a window to get it wrong in.
 */
const quietWindow = (ms = 250): Promise<void> => new Promise((r) => setTimeout(r, ms));

const hasPresenterNotice = (browser: FakeBrowser): boolean =>
  browser.received.some((c) => c.name === ReticleCommand.PRESENTER);

describe('agent presence → panel notice (end to end)', () => {
  it('drops a clear ended notice to the browser when the last agent disconnects', async () => {
    const port = await startStack();
    const browser = new FakeBrowser(port, 'sess-presence');
    await browser.open();
    await waitFor(() => 1 === bridge?.sessions.count(), 'the browser session to register');

    // An agent attaches, then stops (its MCP connection drops).
    const agent = await openSse(port);
    await waitFor(() => true === presence.at(-1), 'the agent SSE to register as present');
    agent.destroy();
    await waitFor(() => hasPresenterNotice(browser), 'the ended notice to reach the browser');

    const presenter = browser.received.find((c) => c.name === ReticleCommand.PRESENTER);
    expect(presenter).toBeDefined();
    expect(presenter?.args['state']).toBe(SessionState.ENDED);
    expect(presenter?.args['text']).toBe(AGENT_STOPPED_NOTICE);
    browser.close();
  });

  it('does NOT end the session while another agent is still attached', async () => {
    const port = await startStack();
    const browser = new FakeBrowser(port, 'sess-two-agents');
    await browser.open();
    await waitFor(() => 1 === bridge?.sessions.count(), 'the browser session to register');

    const a = await openSse(port);
    const b = await openSse(port);
    await waitFor(() => true === presence.at(-1), 'both agent SSEs to register as present');
    a.destroy(); // one agent leaves — the other is still driving
    await quietWindow(); // negative check: give it a window to wrongly end the session

    expect(hasPresenterNotice(browser)).toBe(false);

    b.destroy(); // now the last agent leaves → the human gets the notice
    await waitFor(
      () => hasPresenterNotice(browser),
      'the ended notice after the last agent leaves',
    );
    expect(hasPresenterNotice(browser)).toBe(true);
    browser.close();
  });
});

import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { REPO_ROOT } from './machine/repo-root.js';

/**
 * The final `gate` job is the one check a merge is allowed to depend on. It passes when every job it
 * lists in `needs` either succeeded or was skipped.
 *
 * Which makes the `needs` list load-bearing in a way that is easy to miss: a job that is NOT on it is
 * invisible to the aggregate. It can go red on every run, and the one required check still goes
 * green. The workflow says so in a comment -- "Adding a job to the workflow is half the work; this
 * line is the other half" -- and a comment is a thing you have to remember. This is the same rule
 * with a test behind it.
 *
 * The cost of getting it wrong is not theoretical for this repo. `rust` is the only job in CI that
 * compiles `adapters/realm/tauri` at all, because that package sits outside every JavaScript gate. While it
 * was missing from this list, a red Rust build merged clean.
 */

const WORKFLOWS_DIR = join(REPO_ROOT, '.github', 'workflows');
const CI_FILE = join(WORKFLOWS_DIR, 'ci.yml');

/**
 * Jobs that run on a pull request from a workflow OTHER than ci.yml.
 *
 * These can never be in the aggregate's `needs`: a job can only wait on jobs in its own workflow
 * file. So the aggregate going green says nothing at all about them. The only thing that can make one
 * of them block a merge is the repository's branch-protection setting, which lives in the GitHub UI
 * and not in this repository -- so nothing here can check that it is set.
 *
 * They are listed anyway, and the list is the point: a gate that runs on every pull request and
 * cannot fail one is machine time spent for no decision. Whoever adds a workflow has to come here and
 * say which it is.
 */
const PR_JOBS_OUTSIDE_THE_AGGREGATE: Record<string, string> = {
  'codeql.yml': 'security scan -- only blocks if branch protection requires it',
  'dco.yml': 'sign-off check on contributions',
  'labeler.yml': 'adds labels; nothing depends on it passing',
  'dependabot-auto-merge.yml':
    'not a gate: enables auto-merge on Dependabot patch/minor PRs, which the queue still gates',
  'welcome.yml': 'not a gate: greets a first issue or PR',
};

/**
 * Jobs that are deliberately outside the aggregate, and why. Adding to this list is allowed; doing it
 * silently is not, which is the whole point of the list being here rather than in somebody's head.
 */
const OUTSIDE_THE_AGGREGATE: Record<string, string> = {
  // The aggregate itself. It cannot wait on its own result.
  gate: 'is the aggregate',
  // Fires a notification at another repository, only on a push to main, and reports failure without
  // ever failing -- the verdict it asks for lives in the other repo's run, not in this one. Nothing
  // about this PR is unproven if it does not fire.
  'fixtures-dispatch': 'notifies another repo; non-fatal by design, and never runs on a PR',
  'nightly-watch':
    'schedule only; opens or comments on the nightly-red issue. Cannot fail a PR (skipped on every PR).',
};

/** Every top-level job name in the workflow, in file order. */
function jobNames(yaml: string): string[] {
  const lines = yaml.split('\n');
  const start = lines.findIndex((line) => 'jobs:' === line.trim());
  if (start < 0) return [];
  const names: string[] = [];
  for (const line of lines.slice(start + 1)) {
    // A top-level key at any indentation other than two spaces has left the jobs block.
    if (/^\S/.test(line)) break;
    const match = /^ {2}([a-z][a-z0-9-]*):\s*$/.exec(line);
    if (match?.[1] !== undefined) names.push(match[1]);
  }
  return names;
}

/** The job names listed in the aggregate's `needs:` block. */
function aggregateNeeds(yaml: string): string[] {
  const afterGate = yaml.slice(yaml.indexOf('\n  gate:\n'));
  const needsAt = afterGate.indexOf('needs:');
  const block = afterGate.slice(needsAt, afterGate.indexOf(']', needsAt));
  return [...block.matchAll(/[a-z][a-z0-9-]*/g)]
    .map((m) => m[0])
    .filter((name) => 'needs' !== name);
}

/** Workflow files that run on a pull request, other than ci.yml. */
function otherPrWorkflows(): string[] {
  return readdirSync(WORKFLOWS_DIR)
    .filter((file) => file.endsWith('.yml') && 'ci.yml' !== file)
    .filter((file) => readFileSync(join(WORKFLOWS_DIR, file), 'utf8').includes('pull_request'))
    .sort();
}

describe('gates that run on a pull request are accounted for', () => {
  it('every pull-request workflow outside ci.yml is listed with how it is enforced', () => {
    expect(
      otherPrWorkflows(),
      'A workflow runs on pull requests but is not listed in PR_JOBS_OUTSIDE_THE_AGGREGATE. Its jobs ' +
        'cannot be added to the aggregate -- a job only waits on jobs in its own file -- so add it to ' +
        'that list saying how it is enforced, or move its jobs into ci.yml where the aggregate can ' +
        'see them. A gate that runs on every pull request and cannot fail one is machine time spent ' +
        'for no decision.',
    ).toEqual(Object.keys(PR_JOBS_OUTSIDE_THE_AGGREGATE).sort());
  });
});

/**
 * Workflows that exist to catch a security problem before it is merged.
 *
 * Named here rather than guessed from the filename, so that adding one is a decision somebody makes
 * rather than something a naming convention does for them.
 */
const SECURITY_WORKFLOWS = ['codeql.yml'];

describe('a security scan runs on every pull request, not just the ones aimed at main', () => {
  it.each(SECURITY_WORKFLOWS)('%s does not filter its pull_request trigger by branch', (file) => {
    // `pull_request: { branches: [main] }` is what GitHub's template ships, and it reads as harmless.
    // In this repository it is not: work lands on a release or feature branch for weeks and only that
    // branch's final merge targets main. So the filter scanned the last merge of a release and none
    // of the pull requests that built it.
    const yaml = readFileSync(join(WORKFLOWS_DIR, file), 'utf8');
    const trigger = yaml.slice(yaml.indexOf('pull_request:'));
    const nextTrigger = trigger.slice(1).search(/\n {2}\w+:/);
    const block = -1 === nextTrigger ? trigger : trigger.slice(0, nextTrigger + 1);
    expect(
      block.includes('branches:'),
      `${file} only scans pull requests aimed at the named branches. Remove the branches filter so ` +
        'every pull request is scanned, whatever it targets.',
    ).toBe(false);
  });
});

describe('the aggregate gate covers every job in ci.yml', () => {
  const yaml = readFileSync(CI_FILE, 'utf8');
  const jobs = jobNames(yaml);
  const needs = aggregateNeeds(yaml);

  it('reads the workflow at all', () => {
    // Without this, a parser that returned nothing would make the real check below pass by having
    // nothing to check -- which is the exact failure shape this file exists to prevent.
    expect(jobs.length).toBeGreaterThan(5);
    expect(needs.length).toBeGreaterThan(5);
  });

  it('every job is watched by the aggregate, or listed as deliberately outside it', () => {
    const unwatched = jobs.filter(
      (job) => !needs.includes(job) && !Object.hasOwn(OUTSIDE_THE_AGGREGATE, job),
    );
    expect(
      unwatched,
      "These CI jobs can fail without failing the one required check. Add each to the `gate` job's " +
        '`needs:` list, or to OUTSIDE_THE_AGGREGATE in this file with the reason it is safe to ignore.',
    ).toEqual([]);
  });

  it('the aggregate does not wait on a job that no longer exists', () => {
    // A renamed or deleted job leaves a stale entry that GitHub resolves to nothing, quietly
    // shrinking what the required check covers.
    expect(needs.filter((name) => !jobs.includes(name))).toEqual([]);
  });
});

/**
 * The package's own test setup runs, alongside the shared one.
 *
 * Incident: the shared options gained `setupFiles` (a temporary HOME for every package), and this
 * package spread them AFTER its own `setupFiles`, so the later key replaced it. `vitest.setup.ts`
 * stopped running: every storage-touching test ran on jsdom's Storage instead of the MockStorage
 * it was written against, and all of them still passed.
 */
import { describe, expect, it } from 'vitest';

describe('the browser package test environment', () => {
  it('installs its own MockStorage', () => {
    expect(globalThis.localStorage.constructor.name).toBe('MockStorage');
  });
});

/**
 * Every CI job either gates a merge or is written down as deliberately not gating.
 *
 * `gate` is the single required status check, and its `needs:` array is hand-maintained. A job absent
 * from that array runs, reports, and is structurally incapable of stopping a merge — the workflow's
 * own comment records that `windows`, `rust`, `rust-macos` and `desktop-e2e` were all in exactly that
 * state, and `rust` is the only thing in CI that compiles `adapters/realm/tauri` at all. Four jobs, four
 * separate discoveries, none of them by a machine.
 *
 * Adding a job to the workflow is half the work; adding it to `needs:` is the other half, and nothing
 * checked the second half. This is the same shape as every other completeness guard here: a registry
 * exists, and something has to prove it is complete.
 */

import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parse } from 'yaml';
import { REPO_ROOT } from '@/machine/repo-root.js';

const REPO = REPO_ROOT;
const WORKFLOW = join(REPO, '.github', 'workflows', 'ci.yml');

/** The aggregate job itself — the thing branch protection requires. */
const GATE = 'gate';

/**
 * Jobs that legitimately do not gate a merge, each with the reason it cannot.
 *
 * The bar is not "this job is unimportant". It is "this job CANNOT fail a PR", which is a property of
 * the job, not an opinion about it. Anything else belongs in `needs:`.
 */
const NOT_A_GATE = new Map<string, string>([
  [
    GATE,
    'the aggregate itself. Listing it in its own `needs:` is a cycle, and it is the job branch ' +
      'protection requires directly.',
  ],
  [
    'fixtures-dispatch',
    'cannot fail a PR in either of the two ways that matter. It is `if: push && ref == main`, so it ' +
      'never runs on a pull request at all; and its one step exits 0 when the token is unset and ' +
      'merely echoes when the dispatch call does not return 204. It asks ANOTHER repo to verify this ' +
      "commit and the verdict lives in that repo's run — a fire-and-forget notification, not a check. " +
      'Adding it to `needs:` would gate merges on a job that is `skipped` on every PR forever.',
  ],
  [
    'nightly-watch',
    'schedule only. It comments on the nightly-red issue. It is `skipped` on every pull request, so ' +
      'listing it in `gate.needs` would teach people to ignore a skip, and it cannot fail a PR.',
  ],
]);

interface Workflow {
  jobs: Record<string, { needs?: string | string[] }>;
}

/** Narrow the parsed YAML at the boundary rather than trusting it. */
function readWorkflow(): Workflow {
  const parsed: unknown = parse(readFileSync(WORKFLOW, 'utf8'));
  if ('object' !== typeof parsed || null === parsed || !('jobs' in parsed))
    throw new Error(`${WORKFLOW} has no jobs map`);
  const jobs: unknown = parsed.jobs;
  if ('object' !== typeof jobs || null === jobs) throw new Error(`${WORKFLOW} jobs is not a map`);
  const out: Workflow['jobs'] = {};
  for (const [name, body] of Object.entries(jobs)) {
    const needs: unknown =
      'object' === typeof body && null !== body && 'needs' in body
        ? (body as { needs: unknown }).needs
        : undefined;
    out[name] =
      'string' === typeof needs
        ? { needs }
        : Array.isArray(needs)
          ? { needs: needs.filter((n): n is string => 'string' === typeof n) }
          : {};
  }
  return { jobs: out };
}

const needsOf = (name: string): readonly string[] => {
  const needs = readWorkflow().jobs[name]?.needs;
  if (undefined === needs) return [];
  return 'string' === typeof needs ? [needs] : needs;
};

describe('every CI job either gates a merge or says why it does not', () => {
  it('finds the workflow and its jobs (a passing test over zero jobs proves nothing)', () => {
    expect(Object.keys(readWorkflow().jobs).length).toBeGreaterThan(10);
  });

  it(`${GATE} exists and depends on real jobs`, () => {
    const jobs = readWorkflow().jobs;
    expect(
      jobs[GATE],
      `${GATE} is the single required status check and it is missing`,
    ).toBeDefined();
    const unknownDeps = needsOf(GATE).filter((n) => !(n in jobs));
    expect(unknownDeps, `${GATE} needs jobs that do not exist in the workflow`).toEqual([]);
  });

  it('no job runs outside the gate without a written reason', () => {
    const gated = new Set(needsOf(GATE));
    const ungated = Object.keys(readWorkflow().jobs).filter(
      (name) => !gated.has(name) && !NOT_A_GATE.has(name),
    );
    expect(
      ungated,
      `these jobs run, report, and cannot stop a merge: ${ungated.join(', ')}. Add each to the ` +
        `\`needs:\` array of the \`${GATE}\` job, or to NOT_A_GATE here with the reason it cannot ` +
        `fail a PR.`,
    ).toEqual([]);
  });

  it('every NOT_A_GATE entry names a job that still exists', () => {
    const jobs = readWorkflow().jobs;
    for (const [name, why] of NOT_A_GATE) {
      expect(name in jobs, `NOT_A_GATE exempts ${name}, which is no longer a job (${why})`).toBe(
        true,
      );
    }
  });

  it('no NOT_A_GATE entry is also in the gate — an exemption that is gated anyway is stale', () => {
    const gated = new Set(needsOf(GATE));
    const contradictory = [...NOT_A_GATE.keys()].filter((n) => gated.has(n));
    expect(
      contradictory,
      `these are exempted here AND listed in \`${GATE}\`'s needs — drop the exemption`,
    ).toEqual([]);
  });
});

/**
 * A scaffold the install gate knows about but CI never runs is coverage on paper only.
 *
 * The gate reads its scaffold list from `install-gate.mjs` and its expectations from
 * `install-baseline.json`; CI runs one matrix cell per scaffold. Those are three lists that have to
 * agree, and nothing made them. Adding a scaffold and forgetting the matrix leaves a baseline
 * nobody checks — silent, and indistinguishable from coverage.
 *
 * This went from five scaffolds to ten in one branch, which is exactly when the drift happens.
 */
describe('every install-gate scaffold runs in CI', () => {
  const baselineIds = (): string[] => {
    const raw = readFileSync(join(REPO, 'apps/e2e/install-baseline.json'), 'utf8');
    return Object.keys(JSON.parse(raw) as Record<string, unknown>).sort();
  };

  /*
   * The scaffold list moved out of `strategy.matrix` and into the `install_matrix` step that builds
   * the matrix, because WHICH cells run now depends on the event: a pull request runs three Windows
   * scaffolds and everything else runs ten. `ALL` is still the one list of every scaffold CI knows
   * about, which is what this guard is asking after — so it reads that, and still returns nothing
   * (failing loudly below) if the shape changes again.
   */
  const matrixIds = (): string[] => {
    const yml = readFileSync(join(REPO, '.github/workflows/ci.yml'), 'utf8');
    const block = /^\s*ALL='([^']+)'/m.exec(yml);
    if (null === block) return [];
    return (block[1] ?? '')
      .split(/\s+/)
      .map((entry) => entry.trim())
      .filter((entry) => entry.length > 0)
      .sort();
  };

  it('the CI matrix and the recorded baseline name the same scaffolds', () => {
    const inBaseline = baselineIds();
    const inMatrix = matrixIds();

    expect(
      inMatrix.length,
      'no scaffold matrix found in ci.yml — has the job changed shape?',
    ).toBeGreaterThan(0);

    expect(
      inBaseline.filter((id) => !inMatrix.includes(id)),
      'these scaffolds have a recorded baseline but no CI cell, so nothing ever runs them',
    ).toEqual([]);

    expect(
      inMatrix.filter((id) => !inBaseline.includes(id)),
      'these CI cells name a scaffold with no recorded baseline, so the cell fails asking for one',
    ).toEqual([]);
  });
});

/**
 * A retry must be scoped to the failures where retrying is safe, and must always say it retried.
 *
 * `scripts/ci-run.mjs` exists because Windows runners intermittently refuse to START a process:
 * exit `-1073741502` (`0xC0000142`, STATUS_DLL_INIT_FAILED), no output, sometimes 0.02s in. The
 * product is fine and the red is indistinguishable from a real failure until somebody recognises an
 * NT status code.
 *
 * The dangerous version of this fix is a retry-everything wrapper, which hides real failures and
 * turns a flaky suite into a trusted-but-wrong one. So the decision is pinned here rather than left
 * to a reading of the script:
 *
 *   - retry ONLY the codes that mean the process never started, where no user code ran and there is
 *     no partial state for a second attempt to be confused by
 *   - a normal test failure (1) is never retried
 *   - every retry is announced, and the announcement says it is an ENVIRONMENT failure
 *
 * Tested from this package because `scripts/` has no test setup of its own and this is the gate that
 * always runs. See https://github.com/reticlehq/reticle/issues/273.
 */

import { describe, expect, it } from 'vitest';
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { REPO_ROOT } from '@/machine/repo-root.js';

const REPO = REPO_ROOT;
const SCRIPT = join(REPO, 'scripts', 'ci-run.mjs');

const load = async (): Promise<{
  runnerLevelFailure: (code: number | null) => string | null;
  explain: (code: number, detail: string, willRetry: boolean) => string;
  RUNNER_LEVEL_EXIT_CODES: Map<number, string>;
  runnerLevelInOutput: (output: string) => string | null;
  runOnce: (command: string, args: string[]) => Promise<{ code: number | null; output: string }>;
}> => (await import(SCRIPT)) as never;

describe('only a failure to START the process is retried', () => {
  it('recognises STATUS_DLL_INIT_FAILED, the one actually observed', async () => {
    const { runnerLevelFailure } = await load();
    expect(runnerLevelFailure(-1073741502)).toContain('0xC0000142');
  });

  it('does NOT retry an ordinary test failure', async () => {
    // The line between a useful wrapper and one that hides defects. Exit 1 is a suite that ran and
    // failed; running it again would either waste a runner or, worse, pass on a flake and bury a
    // real regression.
    const { runnerLevelFailure } = await load();
    expect(runnerLevelFailure(1)).toBeNull();
  });

  it('does NOT retry a success, a signal death, or an unknown code', async () => {
    const { runnerLevelFailure } = await load();
    expect(runnerLevelFailure(0)).toBeNull();
    expect(runnerLevelFailure(137)).toBeNull(); // SIGKILL, e.g. the OOM killer — a real signal
    expect(runnerLevelFailure(-9)).toBeNull();
    expect(runnerLevelFailure(null)).toBeNull();
  });

  it('keeps the retryable set small and closed', async () => {
    // Deliberately not "any large negative number". A crash inside a real test can also produce an
    // unusual code, and retrying that would hide a genuine defect behind an infrastructure excuse.
    const { RUNNER_LEVEL_EXIT_CODES } = await load();
    expect(RUNNER_LEVEL_EXIT_CODES.size).toBeLessThanOrEqual(4);
  });
});

describe('the log says which kind of failure this was', () => {
  it('names it an environment failure and says no user code ran', async () => {
    const { explain, RUNNER_LEVEL_EXIT_CODES } = await load();
    const detail = RUNNER_LEVEL_EXIT_CODES.get(-1073741502) ?? '';
    const text = explain(-1073741502, detail, true);

    // The whole point: a reader who has never seen 0xC0000142 should not have to look it up.
    expect(text).toContain('environment failure');
    expect(text).toContain('not a test failure');
    expect(text).toContain('no user code ran');
  });

  it('announces the retry, so a silent second attempt is impossible', async () => {
    const { explain } = await load();
    expect(explain(-1073741502, 'detail', true)).toContain('Retrying once');
  });

  it('says so when the retry hit it too, rather than going quiet', async () => {
    const { explain } = await load();
    const text = explain(-1073741502, 'detail', false);
    expect(text).toContain('retry hit it as well');
    expect(text).not.toContain('Retrying once');
  });
});

/**
 * The exit code is not the only place a runner-level failure shows up.
 *
 * Every step this wrapper wraps runs through turbo, and turbo CATCHES a child's exit code and exits
 * 1 itself, printing the real one:
 *
 *   ERROR  @reticlehq/vite-plugin#build: command (...) pnpm.CMD run build exited (-1073741502)
 *   ERROR  run failed: command  exited (-1073741502)
 *   Process completed with exit code 1
 *
 * So the wrapper's own child exits 1 — correctly not retryable — and the STATUS_DLL_INIT_FAILED
 * underneath it was invisible. Watching only the exit code made this useless for exactly the
 * commands it wraps, which is not a hypothetical: it turned main red on a changelog-only commit
 * while this wrapper was live and did nothing.
 */
describe('a runner-level failure swallowed by an inner wrapper is still recognised', () => {
  it('finds the NT status in turbo’s own error line', async () => {
    const { runnerLevelInOutput } = await load();
    const turbo =
      'ERROR  @reticlehq/vite-plugin#build: command (D:\\a\\reticle) pnpm.CMD run build exited (-1073741502)\n' +
      'ERROR  run failed: command  exited (-1073741502)\n';
    expect(runnerLevelInOutput(turbo)).toContain('0xC0000142');
  });

  it('says nothing about ordinary output', async () => {
    const { runnerLevelInOutput } = await load();
    expect(runnerLevelInOutput('3776 tests passed\nDone in 12s\n')).toBeNull();
    expect(runnerLevelInOutput('')).toBeNull();
  });

  it('does not fire on an exit code that merely resembles one', async () => {
    // The scan is over a closed list of full codes, not a pattern for "large negative number".
    const { runnerLevelInOutput } = await load();
    expect(runnerLevelInOutput('exited (-1073741) and (-107374150)')).toBeNull();
  });
});

/**
 * The wrapper waits for the command, not for everything the command left running.
 *
 * It used to resolve on the child's `close`, which fires only once every holder of the stdout and
 * stderr pipes has let go. On Windows a process started during the build outlived turbo and kept the
 * pipe open, so a `pnpm build` that printed "16 successful" at 12:00 held its step until the job's
 * 30-minute timeout cancelled it, and the runner's cleanup then reported "Terminate orphan process
 * (node)". Seen on reticlehq/reticle jobs 114602419311 and 114598711779 (both after `typecheck`
 * had finished) and on a fork qualification run after `build`.
 */
describe('a process the command leaves behind does not hold the step open', () => {
  // Starts a grandchild that inherits the pipes and outlives its parent, prints the grandchild's pid
  // so the test can stop it, writes a line, and exits 0.
  const LEAVES_ONE_BEHIND = [
    "const { spawn } = require('node:child_process');",
    "const g = spawn(process.execPath, ['-e', 'setTimeout(() => {}, 120000)'], { stdio: 'inherit', detached: true });",
    'g.unref();',
    "process.stdout.write('grandchild ' + g.pid + '\\n');",
    "process.stdout.write('build finished\\n');",
  ].join('\n');

  it('returns the exit code once the command exits, keeping the output it wrote', async () => {
    const { runOnce } = await load();
    // From a file, not `-e`: on Windows the wrapper runs through cmd.exe, which ends a multi-line
    // argument at its first newline.
    const dir = mkdtempSync(join(tmpdir(), 'ci-run-'));
    const script = join(dir, 'leaves-one-behind.cjs');
    writeFileSync(script, LEAVES_ONE_BEHIND);
    const result = await runOnce(process.execPath, [script]);
    const pid = Number(/grandchild (\d+)/.exec(result.output)?.[1]);
    try {
      expect(result.code).toBe(0);
      expect(result.output).toContain('build finished');
    } finally {
      if (Number.isInteger(pid)) {
        try {
          process.kill(pid);
        } catch {
          // already gone
        }
      }
      rmSync(dir, { recursive: true, force: true });
    }
  }, 60_000); // A bound on a hang, not a duration assertion: before the fix this waited the full 120 s.
});

import { describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';

/**
 * Every `vi.mock` path names a file that exists.
 *
 * A mock specifier is a string, and moving the file it names does not break the build, does not
 * upset the type checker, and does not fail the mock. It makes the mock match nothing. The real
 * module then loads in its place, and the test carries on against code it believed it had
 * replaced.
 *
 * That happened while grouping `features/flows`: a test mocked `./server-verify.js`, the file
 * moved into `suite/`, and the real module loaded. It failed loudly, but only by luck -- the real
 * module wanted an export that a NEIGHBOURING mock did not provide. Had it needed nothing extra,
 * it would have run for real inside a test written on the assumption that it could not, and the
 * test would have passed.
 *
 * So the invariant is the cheap half: a mock that names a path must name a path that is there.
 * This says nothing about whether mocking that module was wise, only that the string still points
 * at something.
 */

const REPO_ROOT = execFileSync('git', ['rev-parse', '--show-toplevel'], {
  cwd: __dirname,
  encoding: 'utf8',
}).trim();

/** Relative specifiers only. A bare name is a package, and resolving those is node's business. */
const MOCK_CALL = /vi\.(?:mock|doMock|unmock)\(\s*(['"])(\.[^'"]+)\1/g;

interface Mock {
  readonly file: string;
  readonly specifier: string;
}

function everyMock(): Mock[] {
  const tracked = execFileSync('git', ['ls-files', '*.ts', '*.tsx', '*.mts'], {
    cwd: REPO_ROOT,
    encoding: 'utf8',
  })
    .trim()
    .split('\n')
    .filter((line) => '' !== line);
  const found: Mock[] = [];
  for (const file of tracked) {
    const source = readFileSync(join(REPO_ROOT, file), 'utf8');
    for (const call of source.matchAll(MOCK_CALL)) {
      const specifier = call[2];
      if (undefined !== specifier) found.push({ file, specifier });
    }
  }
  return found;
}

/** A mock names a built `.js` path; the source beside it is `.ts` or `.tsx`. */
function pointsAtSomething(mock: Mock): boolean {
  const asTs = resolve(REPO_ROOT, dirname(mock.file), mock.specifier.replace(/\.js$/, '.ts'));
  return (
    existsSync(asTs) ||
    existsSync(asTs.replace(/\.ts$/, '.tsx')) ||
    existsSync(asTs.replace(/\.ts$/, '.js'))
  );
}

describe('every vi.mock names a file that is there', () => {
  it('finds mocks at all, so a pass is not a pass over none', () => {
    // Without this the whole check is green on a regex that stopped matching. Measured 9
    // relative specifiers across the repository on 2026-09-11; the floor sits below that so an
    // ordinary deletion does not fail here, and well above zero so a dead regex does.
    expect(everyMock().length).toBeGreaterThanOrEqual(5);
  });

  it('resolves every relative mock specifier', () => {
    const dangling = everyMock()
      .filter((mock) => !pointsAtSomething(mock))
      .map((mock) => `${mock.file} mocks ${mock.specifier}`)
      .sort();
    expect(
      dangling,
      'these mocks name a file that does not exist. The mock matches nothing, so the REAL module ' +
        'loads and the test runs against the code it meant to replace — which usually passes.',
    ).toEqual([]);
  });
});

import { describe, expect, it } from 'vitest';
import { fixturePortFor, seedFromStorageState } from './storage-fixture.js';
import type { RealInputProvider } from './real-input.js';

/**
 * The port that turns a driven browser into somewhere a suite can start from.
 *
 * A realm offers `applyFixture` only when something can honour it, and on the web that is not a
 * property of the realm — it is a property of the connection. Reading the wire settled it: there is
 * a `storage_read` command and no storage WRITE, and a page cannot write an httpOnly cookie from
 * inside itself, which is the entire point of httpOnly. So an ATTACHED session can never restore
 * auth however much is added to the SDK, and a DRIVEN page can, because a browser context sits
 * behind it.
 *
 * This is therefore the one place that decides whether a fixture is available at all, and the answer
 * is "no" far more often than it is "yes" — which is correct, and merely slower.
 */

const URL = 'http://localhost:4312/';

function provider(over: Partial<RealInputProvider> = {}): RealInputProvider {
  return {
    isAvailableFor: () => Promise.resolve(true),
    perform: () => Promise.resolve({ ok: true }),
    ...over,
  } as unknown as RealInputProvider;
}

describe('when a fixture port is available at all', () => {
  it('is not offered by a provider that cannot do storage', async () => {
    // The common case, and the one that must NOT quietly produce a half-working fixture: a provider
    // with no storage support omits the methods entirely, exactly as it does for screenshots.
    expect(await fixturePortFor(provider(), URL)).toBeUndefined();
  });

  it('is not offered when no driven page matches this session', async () => {
    // A provider that COULD do storage, for a page it is not driving. Answering here would restore
    // state into whatever page it happened to find, which is worse than not answering.
    const p = provider({
      isAvailableFor: () => Promise.resolve(false),
      storageState: () => Promise.resolve({ cookies: [] }),
      applyStorageState: () => Promise.resolve(true),
    });
    expect(await fixturePortFor(p, URL)).toBeUndefined();
  });

  it('is offered when the provider drives this page and can read its storage', async () => {
    const p = provider({
      storageState: () => Promise.resolve({ cookies: [{ name: 'sid' }] }),
      applyStorageState: () => Promise.resolve(true),
    });
    expect(await fixturePortFor(p, URL)).toBeDefined();
  });
});

describe('what the port carries', () => {
  const working = (): { p: RealInputProvider; applied: unknown[] } => {
    const applied: unknown[] = [];
    const p = provider({
      storageState: () => Promise.resolve({ cookies: [{ name: 'sid', value: 'abc' }] }),
      applyStorageState: (_url: string, state: unknown) => {
        applied.push(state);
        return Promise.resolve(true);
      },
    });
    return { p, applied };
  };

  it('captures the browser context state verbatim, because only the browser can read it back', async () => {
    const { p } = working();
    const port = await fixturePortFor(p, URL);
    expect(await port?.capture()).toEqual({ cookies: [{ name: 'sid', value: 'abc' }] });
  });

  it('puts it back unchanged', async () => {
    const { p, applied } = working();
    const port = await fixturePortFor(p, URL);
    await port?.apply({ cookies: [{ name: 'sid', value: 'abc' }] });
    expect(applied).toEqual([{ cookies: [{ name: 'sid', value: 'abc' }] }]);
  });

  it('THROWS when the browser refused to restore, rather than reporting a fixture that is not there', async () => {
    // Silence here is the whole failure mode: a suite that believes it is signed in and is not
    // produces fifty flows failing for a reason none of them names.
    const p = provider({
      storageState: () => Promise.resolve({ cookies: [] }),
      applyStorageState: () => Promise.resolve(false),
    });
    const port = await fixturePortFor(p, URL);
    await expect(port?.apply({ cookies: [] })).rejects.toThrow(/restore|driven|page/i);
  });
});

/**
 * Turning what a browser context saved into what a lease can be booted with.
 *
 * The boot path already existed and I had written down that it did not — `SeedStorage` seeds
 * cookies, localStorage and sessionStorage into an isolated context BEFORE the first navigation,
 * which is exactly and only when a fixture can work. So the gap was never the plumbing; it was that
 * nothing translated between the shape a browser hands back and the shape a lease takes.
 *
 * The two do not line up, and the mismatch matters. Playwright's state is per-ORIGIN, and a lease is
 * booted at one URL: seeding another origin's localStorage into this page would write keys that
 * belong to a site this run never visits. And `storageState()` does not capture sessionStorage at
 * all, so a fixture cannot promise it — a suite relying on a sessionStorage flag would get a
 * silently empty one, which is the quiet half-restore this whole path avoids.
 */
describe('booting a lease from state a browser saved', () => {
  const state = {
    cookies: [{ name: 'sid', value: 'abc', domain: 'localhost', path: '/' }],
    origins: [
      { origin: 'http://localhost:4312', localStorage: [{ name: 'token', value: 'xyz' }] },
      { origin: 'https://elsewhere.test', localStorage: [{ name: 'other', value: 'nope' }] },
    ],
  };

  it('carries the cookies, which are what auth usually is', () => {
    expect(seedFromStorageState(state, URL)?.cookies).toEqual(state.cookies);
  });

  it('carries only THIS origin’s local storage', () => {
    // Seeding another origin's keys into this page writes for a site the run never visits.
    expect(seedFromStorageState(state, URL)?.local).toEqual({ token: '<REDACTED>' });
  });

  it('promises no sessionStorage, because a browser context state does not carry it', () => {
    // Absent, not empty-and-claimed. A suite relying on a flag it was never given should find
    // nothing rather than a silently empty object that looks restored.
    expect(seedFromStorageState(state, URL)?.session).toBeUndefined();
  });

  it('is nothing at all when the saved state holds nothing for this origin', () => {
    const elsewhere = { cookies: [], origins: [state.origins[1]] };
    expect(seedFromStorageState(elsewhere, URL)).toBeUndefined();
  });

  it('is nothing when handed something that is not a browser state', () => {
    expect(seedFromStorageState(undefined, URL)).toBeUndefined();
    expect(seedFromStorageState('signed-in', URL)).toBeUndefined();
  });
});

import { describe, expect, it } from 'vitest';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { TOOLS } from './tools.js';
import { ReticleTool } from '@reticlehq/core';
import { REPO_ROOT } from '@/machine/repo-root.js';
import { publishedPackageDirs } from '@/workspace-packages.js';

/**
 * Every `reticle_*` tool an e2e spec calls must still exist on the surface.
 *
 * This exists because the opposite happened and nothing noticed. A consolidation merged 56 tools down
 * to 41 — `reticle_record_start`/`_stop` became `reticle_record { action }`, `reticle_end_session`
 * became `reticle_session { action: 'end' }`, `reticle_flow_list` became `reticle_flow { action }` —
 * and four specs kept calling the old names. They died on `TOOLS.find(...)` returning undefined,
 * taking flow record/replay, self-heal, run history and live control with them, across bench-app AND
 * next-smoke. That is a whole framework's worth of coverage, dark for an unknown number of commits.
 *
 * It went unnoticed because the e2e battery needs three servers and ~8 minutes (measured; it was
 * documented as "~20 min" for months, and briefly as "~70s" — both wrong), so it is not in
 * `test:unit` — which is what actually runs. The battery cannot move into the unit gate, but the
 * failure mode that killed it is a name lookup, and a name lookup is checkable in milliseconds.
 *
 * So this is deliberately NOT an e2e test. It is a static cross-check placed in the gate that runs,
 * because the pattern in this repo is unambiguous: every rule a machine enforces has held, and every
 * rule left to prose has been violated. A renamed tool now fails here, in a second, instead of
 * silently deleting a spec's coverage.
 */
const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = REPO_ROOT;
const SPEC_DIR = join(REPO, 'apps', 'e2e', 'specs');
/**
 * The bench harnesses drive the SAME tool surface and rot the SAME way — which is not hypothetical:
 * the identical 56->41 consolidation that killed four e2e specs ALSO killed nine harnesses under
 * bench/harness, and this guard did not cover them because it was written to the shape of the first
 * incident instead of the shape of the failure. They called reticle_record_start/stop long after
 * those became reticle_record{action}; every replay, determinism and regression-efficiency number in
 * bench/ was produced by a harness that could not call its own tool, and the published
 * "128-2574x cheaper" claim traces back to one of them. Guarding one directory against a
 * repo-wide failure mode is what let it happen twice.
 */
const BENCH_DIR = join(REPO, 'bench');

/**
 * And the demo harnesses under `apps/`, because it happened a THIRD time exactly as predicted.
 *
 * The note above ends "guarding one directory against a repo-wide failure mode is what let it happen
 * twice", and then the guard was extended to a second directory rather than to the failure. So
 * a demo harness under `apps/` kept calling `reticle_wait_ready` after it was retired from the
 * surface, and every one of that demo's five steps died on `TOOLS.find(...).handler` — the identical
 * crash, in a demo whose whole point is showing Reticle catching what other gates miss.
 *
 * Scanned as a tree rather than a list of known directories: the next harness will be written
 * somewhere none of us predicted, and a guard that has to be told about it is a guard that will miss
 * it again.
 */
const APPS_DIR = join(REPO, 'apps');

/** Tool names referenced as string literals in a spec, e.g. T('reticle_query', …). */
const TOOL_REF = /'(reticle_[a-z0-9_]+)'/g;

/**
 * The universe this guard judges against: names DECLARED as tools.
 *
 * Matching every `reticle_*` token instead flagged 23 telemetry event codes and CLI log identifiers
 * (`reticle_status`, `reticle_daemon_stopped`) that were never tools and never will be. A name is
 * only evidence of drift if it was a tool once and is not on the surface now — which is exactly what
 * a consolidation leaves behind.
 */
const DECLARED_TOOLS = new Set<string>(Object.values(ReticleTool));

/**
 * Names that ARE callable, just not in the default profile — so naming them in guidance is correct.
 *
 * `TOOLS` is one profile's surface, not the universe. The progressive-disclosure tools are advertised
 * only when that profile is active, and treating their absence from the default list as drift would
 * flag guidance that is exactly right for the reader who has them. This is the distinction the guard
 * exists to draw: a FACADE MEMBER (`reticle_flow_list`) cannot be called by its own name in any
 * profile and must not be advertised as if it could; a profile-gated tool can.
 */
/**
 * Real tools that a given surface may not advertise, so naming one is not naming a dead tool.
 *
 * `run`/`tools` are built at MCP registration rather than living in `TOOLS`. `look` is the merged
 * read family: it exists only on the `merged` surface, so `surface-vocabulary.ts` has to be able to
 * name it while resolving which spelling THIS surface uses.
 */
const PROFILE_GATED = new Set<string>([ReticleTool.RUN, ReticleTool.TOOLS, ReticleTool.LOOK]);

/**
 * Names a spec may reference despite being absent from the advertised surface, each with the reason.
 *
 * "Absent" is not the same as "gone", and conflating them cost me a wrong claim in three files: a tool
 * can be RETIRED — handler intact, deliberately unadvertised because something else covers it — and
 * reading only the missing name looks identical to a lost capability. Every entry here states which
 * it is, so the next reader does not have to re-derive it from tools.ts.
 */
const KNOWN_REMOVED = new Map<string, string>([
  [
    'reticle_run_record',
    'RETIRED from the surface, not removed: tools.ts RETIRED_FROM_SURFACE records that flow_replay already auto-records run outcomes, so a manual append was redundant. The handler still exists and works; it is simply not advertised. An earlier note here claimed the capability was lost — it was not, and the claim came from reading a missing tool name without checking the retirement list.',
  ],
  [
    'reticle_affected',
    'MERGED into reticle_verify { action: "affected" }. The remaining references are not calls: `reticle affected` is a CLI COMMAND whose structured log line carries `"event": "reticle_affected"`, and the docs quote that line verbatim. Renaming the event to satisfy this guard was tried and reverted — it is documented output that somebody may be parsing, and breaking a log contract to quiet a false positive is a worse trade than an exemption that says so.',
  ],
  [
    'reticle_record_stop',
    'MERGED into reticle_record { action: "stop" }, and named in a spec on purpose rather than called. `skill-one-call-paths-test` asserts that this spelling is still refused WITH the redirect, because it is the mistake a draft of SKILL.md actually made — the instructions would have been refused at runtime while reading perfectly sensibly. A reference that exists to prove a name is gone is the one case this guard cannot tell from a call, so it is exempted here rather than obscured in the spec.',
  ],
]);

function specFiles(): string[] {
  return readdirSync(SPEC_DIR).filter((f) => f.endsWith('.mjs'));
}

/** Every .mjs under a directory, recursively — harnesses live several directories deep. */
function harnessFiles(dir: string): string[] {
  const out: string[] = [];
  if (!existsSync(dir)) return out;
  for (const entry of readdirSync(dir)) {
    if ('node_modules' === entry || 'dist' === entry || '.next' === entry) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...harnessFiles(full));
    else if (entry.endsWith('.mjs')) out.push(full);
  }
  return out;
}

const benchFiles = (): string[] => harnessFiles(BENCH_DIR);
/**
 * Everything under `apps/` that drives the tool surface, minus the e2e specs the first guard already
 * covers by name. Deduped rather than excluded by path, so a spec moving does not silently drop it
 * from both guards at once.
 */
const appHarnessFiles = (): string[] =>
  harnessFiles(APPS_DIR).filter((f) => !f.startsWith(SPEC_DIR));

describe('e2e specs do not reference tools that no longer exist', () => {
  const advertised = new Set(TOOLS.map((t) => t.name));

  it('finds spec files to check (a passing test over zero specs proves nothing)', () => {
    expect(specFiles().length).toBeGreaterThan(5);
  });

  for (const file of specFiles()) {
    it(`${file} calls only tools that are on the surface`, () => {
      const text = readFileSync(join(SPEC_DIR, file), 'utf8');
      const referenced = [...text.matchAll(TOOL_REF)].map((m) => m[1]);
      // Only a name that WAS a tool is evidence of drift. A spec may legitimately quote a
      // telemetry event code (`reticle_installed`) or a store name, and flagging those told the
      // author to "update the spec" about a string that was never a tool and never will be — a guard
      // that is confidently wrong is worse than one that is silent, because the fix it demands is
      // impossible. Same rule the guidance guards below use.
      const missing = [...new Set(referenced)].filter(
        (n) =>
          n !== undefined &&
          DECLARED_TOOLS.has(n) &&
          !advertised.has(n) &&
          !PROFILE_GATED.has(n) &&
          !KNOWN_REMOVED.has(n),
      );
      expect(
        missing,
        `${file} references ${missing.join(', ')} — renamed or removed from the tool surface. ` +
          'Update the spec, or add the name to KNOWN_REMOVED with the reason if the capability is ' +
          'genuinely gone.',
      ).toEqual([]);
    });
  }

  it('every KNOWN_REMOVED entry is actually removed — stale exemptions rot', () => {
    for (const [name, why] of KNOWN_REMOVED) {
      expect(
        advertised.has(name),
        `${name} is back on the surface; drop its exemption (${why})`,
      ).toBe(false);
    }
  });
});

describe('bench harnesses do not reference tools that no longer exist', () => {
  const advertised = new Set(TOOLS.map((t) => t.name));

  it('finds bench harnesses to check', () => {
    expect(benchFiles().length).toBeGreaterThan(10);
  });

  it('every reticle_* name a bench harness calls is on the surface', () => {
    const broken: string[] = [];
    for (const file of benchFiles()) {
      const text = readFileSync(file, 'utf8');
      // Only names being CALLED — a tool name inside a comment or a results key is not a call.
      const called = [...text.matchAll(/callTool\(\s*'(reticle_[a-z0-9_]+)'/g)].map((m) => m[1]);
      for (const name of new Set(called)) {
        if (name !== undefined && !advertised.has(name) && !KNOWN_REMOVED.has(name)) {
          broken.push(`${file.slice(REPO.length + 1)} -> ${name}`);
        }
      }
    }
    expect(
      broken,
      'These bench harnesses call tools that are not on the surface. They will fail at runtime and ' +
        'produce a number anyway unless the harness checks isError. Fix the call, or add the name to ' +
        'KNOWN_REMOVED with the reason.',
    ).toEqual([]);
  });
});

describe('demo harnesses under apps/ do not reference tools that no longer exist', () => {
  const advertised = new Set(TOOLS.map((t) => t.name));

  it('finds app harnesses to check', () => {
    expect(appHarnessFiles().length).toBeGreaterThan(0);
  });

  it('every reticle_* name an app harness calls is on the surface', () => {
    // Matched by quoted name rather than by `callTool(`, because these harnesses dispatch their own
    // way — a demo once did `TOOLS.find((t) => t.name === name).handler(...)`, which is the
    // line that actually threw. Narrowed by DECLARED_TOOLS for the same reason as the spec guard: a
    // quoted `reticle_installed` is a telemetry code, not a dead tool, and demanding a fix for a
    // name that was never a tool is worse than silence.
    const broken: string[] = [];
    for (const file of appHarnessFiles()) {
      const text = readFileSync(file, 'utf8');
      for (const match of new Set([...text.matchAll(TOOL_REF)].map((m) => m[1]))) {
        if (
          match !== undefined &&
          DECLARED_TOOLS.has(match) &&
          !advertised.has(match) &&
          !PROFILE_GATED.has(match) &&
          !KNOWN_REMOVED.has(match)
        ) {
          broken.push(`${file.slice(REPO.length + 1)} -> ${match}`);
        }
      }
    }
    expect(
      broken,
      'These demo harnesses call tools that are not on the surface. They die on ' +
        '`TOOLS.find(...).handler` at runtime, which reads as the demo being broken rather than as ' +
        'the tool having been renamed. Fix the call, or add the name to KNOWN_REMOVED with the reason.',
    ).toEqual([]);
  });
});

/**
 * The guidance the surface SHIPS is a caller too — and the one an agent actually follows.
 *
 * The two guards above scan callers written as code: specs and harnesses referencing `'reticle_x'`
 * as string literals. They cannot see a tool name embedded in ADVICE — a tool description, an error
 * message, a readiness banner — and that is where the same consolidation rotted a third time. Six
 * user-facing strings still told an agent to call `reticle_record_start`/`_stop` long after those
 * became `reticle_record { action }`, including `reticle_discover`'s own description of the flow
 * workflow and the error you get when a recording is missing. An agent following that guidance
 * verbatim gets "tool not found" and has no way to know the advice was stale rather than its own
 * call being wrong.
 *
 * This guard is deliberately shaped to the FAILURE (a dead name reaching a user) rather than to the
 * incident (specs, then harnesses, then prose).
 */
const SERVER_SRC = join(HERE, '..');
/** Any reticle_* name mentioned anywhere in a source file, quoted or embedded in prose. */
const ANY_TOOL_MENTION = /reticle_[a-z0-9_]+/g;

function serverSources(dir: string = SERVER_SRC): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    if ('node_modules' === entry || 'dist' === entry) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...serverSources(full));
    // tool-names.ts DECLARES the constants; the names there are the vocabulary, not advice.
    else if (entry.endsWith('.ts') && !entry.includes('.test.') && entry !== 'tool-names.ts')
      out.push(full);
  }
  return out;
}

describe('user-facing guidance never names a tool an agent cannot call', () => {
  const advertised = new Set(TOOLS.map((t) => t.name));

  it('finds source files to check', () => {
    expect(serverSources().length).toBeGreaterThan(20);
  });

  it('every reticle_* name in shipped guidance resolves to a live tool', () => {
    const dead: string[] = [];
    for (const file of serverSources()) {
      const text = readFileSync(file, 'utf8');
      // Per LINE, not per file: a whole-file search matches any quote anywhere before the name, which
      // flags ordinary code comments describing the module. Only a name inside a string on its own line
      // is guidance that ships.
      for (const line of text.split('\n')) {
        // `/**` as well as `*` and `//`: a ONE-LINE doc comment starts with `/**`, which neither of
        // the other two prefixes matches, so every single-line `/** … */` was being read as shipped
        // guidance. Found when one legitimately described a tool by name.
        const trimmed = line.trimStart();
        if (trimmed.startsWith('*') || trimmed.startsWith('//') || trimmed.startsWith('/*'))
          continue;
        for (const match of line.match(ANY_TOOL_MENTION) ?? []) {
          if (PROFILE_GATED.has(match)) continue;
          if (!DECLARED_TOOLS.has(match) || advertised.has(match) || KNOWN_REMOVED.has(match))
            continue;
          // A facade is BUILT from its members' constants — `members: { start: ReticleTool.RECORD_START }`
          // wires the surface rather than advising anyone to call it. Only a bare literal is advice.
          if (!/['`"]/.test(line.slice(0, line.indexOf(match)))) continue;
          dead.push(`${file.replace(SERVER_SRC, '')}: ${match}`);
        }
      }
    }
    expect(dead, `guidance names tools that are not on the surface:\n${dead.join('\n')}`).toEqual(
      [],
    );
  });
});

/**
 * The docs a USER pastes are guidance too, and the furthest-out audience.
 *
 * `skills/install-and-verify/SKILL.md` is the same guidance again, published to the agent-skill registry, where
 * the reader arrived by search and has never seen this repo. It is in scope for the same reason.
 *
 * `SKILL.md` is the canonical paste-URL for integrating Reticle and `docs/` ships with it, so a dead
 * tool name there reaches someone with no way at all to check it against the surface. Judged by the
 * same rule as shipped code — a name is drift only if it was DECLARED a tool and is not callable —
 * because prose legitimately mentions Rust symbols (`reticle_tauri::reticle_capture`), store names
 * (`__reticle_renders`) and telemetry codes (`reticle_installed`), none of which are tools. Matching
 * every `reticle_*` token flags eight of those and nothing real, which is how a guard becomes noise
 * and then gets ignored.
 */
describe('shipped docs never name a tool a reader cannot call', () => {
  const advertised = new Set(TOOLS.map((t) => t.name));
  const DOCS = join(REPO, 'docs');

  function docFiles(dir: string = DOCS): string[] {
    const out: string[] = [];
    for (const entry of readdirSync(dir)) {
      if ('node_modules' === entry || entry.startsWith('.')) continue;
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) out.push(...docFiles(full));
      // `.mdx` as well as `.md`. The reference pages are all `.mdx` and every one of them is a
      // list of tool names, so scanning only `.md` meant the guard was blind to precisely the
      // pages most likely to name a tool wrong.
      else if (entry.endsWith('.md') || entry.endsWith('.mdx')) out.push(full);
    }
    return out;
  }

  /**
   * The published skill, which is the same guidance again for a reader who has never seen this repo.
   *
   * They arrived from a skill registry, they have no checkout, and the body delegates its detail to
   * `references/`, so a dead name in one of those files reaches someone with no way at all to check
   * it. Same rule, wider net.
   */
  function walkSkills(dir: string): string[] {
    if (!existsSync(dir)) return [];
    const out: string[] = [];
    for (const entry of readdirSync(dir)) {
      const full = join(dir, entry);
      if (statSync(full).isDirectory()) out.push(...walkSkills(full));
      else if (entry.endsWith('.md')) out.push(full);
    }
    return out;
  }

  /**
   * Both published skill roots, which are two directories for two distribution channels.
   *
   * `skills/` is the skills-CLI package. `plugin/SKILL.md` is the single skill the Claude Code plugin
   * ships, and it is the file a `/reticle` user reads first, so leaving it out of these checks would
   * exempt the most-read guidance in the repo from every rule the rest of it follows.
   */
  function skillFiles(): string[] {
    return [...walkSkills(join(REPO, 'skills')), join(REPO, 'plugin', 'SKILL.md')].filter(
      existsSync,
    );
  }

  it('finds docs to check', () => {
    expect(docFiles().length).toBeGreaterThan(3);
  });

  /**
   * The published package READMEs are in scope, and they are the most-read docs we ship.
   *
   * This guard checked `docs/` and `SKILL.md` only, so `server/README.md` was advertising
   * `reticle_baseline_save`, `reticle_baseline_list` and `reticle_diff` — three names no profile
   * registers (the real tools are `reticle_baseline` and `reticle_visual_diff`) — to every reader on
   * npm, and passed. The logic here was always right; it was simply pointed at the wrong files.
   */
  function shippedReadmes(): string[] {
    // The README of every package we publish, and the one at the top. Not every README in the
    // repository: `bench/README.md` describes an experiment for us, and holding it to what a
    // stranger on npm can call would be holding it to the wrong standard.
    const out = [join(REPO, 'README.md')];
    for (const dir of publishedPackageDirs()) {
      const readme = join(dir, 'README.md');
      if (existsSync(readme)) out.push(readme);
    }
    return out;
  }

  it('finds shipped READMEs to check', () => {
    expect(shippedReadmes().length).toBeGreaterThan(3);
  });

  /**
   * `llms.txt`, which is the file most likely to be read without a way to check it.
   *
   * It exists to be pasted whole into a model, and `SKILL.md` tells an agent to fetch it FIRST, so a
   * dead tool name there is repeated with total confidence by something that cannot look it up. It
   * was outside every check on this list: at the v3 release it still advertised `reticle_query` and
   * `reticle_act_sequence`, both retired when seventeen tools were merged into nine, and claimed the
   * default surface was 18 tools when `defaultAdvertisedNames` returns 9. Three wrong facts in the
   * one document whose whole purpose is being quoted verbatim.
   */
  function briefingFiles(): string[] {
    return [join(REPO, 'llms.txt')].filter(existsSync);
  }

  it('finds the LLM briefing to check', () => {
    expect(briefingFiles().length, 'llms.txt moved or vanished, so this guard checks nothing').toBe(
      1,
    );
  });

  it('every declared tool name in the docs is one a reader can actually call', () => {
    const dead: string[] = [];
    for (const file of [
      ...docFiles(),
      ...shippedReadmes(),
      join(REPO, 'SKILL.md'),
      ...skillFiles(),
      ...briefingFiles(),
    ]) {
      const text = readFileSync(file, 'utf8');
      for (const match of text.match(ANY_TOOL_MENTION) ?? []) {
        if (!DECLARED_TOOLS.has(match) || advertised.has(match)) continue;
        if (PROFILE_GATED.has(match) || KNOWN_REMOVED.has(match)) continue;
        dead.push(`${file.replace(REPO, '')}: ${match}`);
      }
    }
    expect(dead, `docs name tools that are not callable:\n${dead.join('\n')}`).toEqual([]);
  });

  /**
   * `npx reticle` runs SOMEBODY ELSE'S PACKAGE.
   *
   * `reticle` is a bin name `@reticlehq/server` installs, not a package on npm — the name belongs to
   * an unrelated project. `npx <name>` resolves the PACKAGE, so `npx reticle init` fetches a
   * stranger's code from the registry unless a local bin already shadows it, which on a first install
   * it cannot. This shipped on 110 lines across 36 doc pages, including the first command on the
   * quickstart, where by definition nothing of ours is installed yet.
   *
   * The README already states the rule in prose and the docs violated it anyway, which is the usual
   * result of a rule a machine does not enforce. Matched on `npx reticle` only: a BARE `reticle
   * doctor` in captured CLI output is quoting the bin correctly and is not this bug.
   */
  it('no shipped doc tells a reader to npx a package we do not own', () => {
    const wrong: string[] = [];
    for (const file of [
      ...docFiles(),
      ...shippedReadmes(),
      join(REPO, 'SKILL.md'),
      ...skillFiles(),
    ]) {
      const text = readFileSync(file, 'utf8');
      text.split('\n').forEach((line, i) => {
        if (/npx\s+(--[a-z-]+\s+)*reticle(?![a-z@/-])/.test(line))
          wrong.push(`${file.replace(REPO, '')}:${i + 1}: ${line.trim()}`);
      });
    }
    expect(
      wrong,
      `these tell a reader to run an npm package we do not own — use \`npx @reticlehq/server\`:\n${wrong.join('\n')}`,
    ).toEqual([]);
  });

  /**
   * A runnable shell block must never assume the `reticle` bin is on the reader's PATH, except
   * in the README after its installer has explicitly installed the bin and checked that PATH.
   *
   * The reader of these pages installed nothing: they arrived from a paste-URL or a registry and
   * reach for `npx`. A bare `reticle telemetry disable` in a bash fence is a command that either
   * fails with "command not found" or, worse, gets prefixed with `npx` by an agent trying to be
   * helpful, which fetches the unrelated package named `reticle`.
   *
   * Scoped to fences the reader would COPY (bash/sh/shell/console) rather than to every mention.
   * Captured CLI output legitimately prints `reticle doctor` as its own header, and the usage block
   * legitimately lists commands by their bin name; neither is an instruction, and rewriting the 180
   * inline prose references would make the prose worse without helping anybody.
   *
   * The earlier sweep of this repo matched `^reticle ` and therefore missed the one real offender,
   * which was indented two spaces inside a list item. Hence a fence-aware check rather than a
   * line-prefix one.
   */
  it('no runnable shell block assumes the reticle bin is on PATH', () => {
    const RUNNABLE = new Set(['bash', 'sh', 'shell', 'console']);
    const bare: string[] = [];
    for (const file of [
      ...docFiles(),
      ...shippedReadmes(),
      join(REPO, 'SKILL.md'),
      ...skillFiles(),
    ]) {
      let fence: string | null = null;
      const lines = readFileSync(file, 'utf8').split('\n');
      const readmeInstaller =
        file === join(REPO, 'README.md')
          ? lines.findIndex((line) => line.includes('install/install.sh | sh'))
          : -1;
      lines.forEach((line, i) => {
        const open = /^\s*```(\w*)/.exec(line);
        if (open) {
          fence = null === fence ? (open[1] ?? '') : null;
          return;
        }
        if (null === fence || !RUNNABLE.has(fence)) return;
        if (
          /^\s*(\$ )?reticle\s+[a-z]/.test(line) &&
          !(readmeInstaller >= 0 && i > readmeInstaller)
        )
          bare.push(`${file.replace(REPO, '')}:${i + 1}: ${line.trim()}`);
      });
    }
    expect(
      bare,
      `these shell blocks assume the \`reticle\` bin is installed. The reader used npx to get here, so write \`npx @reticlehq/server <command>\`:\n${bare.join('\n')}`,
    ).toEqual([]);
  });

  /**
   * The docs site does not use em dashes. Anywhere: not in a heading, not in body text.
   *
   * A house style rule rather than a correctness one, which is exactly why it needs a machine. The
   * docs were swept clean of them once and the very next edit to `frameworks.mdx` put two back, by
   * someone who had been told the rule an hour earlier. That is the pattern this file already names:
   * every rule enforced by a check has held, and every rule left to prose has been violated.
   *
   * Scoped to the docs site and the published skill files: `docs/`, `SKILL.md`, and `skills/`.
   * `CHANGELOG.md` and the source comments are out of scope for good: a changelog is a written
   * record in a different voice.
   *
   * PROSE only. Fenced blocks and inline code spans are skipped, because a good share of the dashes
   * in these pages sit inside CAPTURED CLI OUTPUT — `doctor`'s diagnosis lines, `kill`'s refusal JSON
   * — and those are quotations of what the program actually prints. "Fixing" them would make the docs
   * disagree with the binary, which is a worse defect than the one this rule is about.
   */
  it('no docs page uses an em dash in prose', () => {
    const wrong: string[] = [];
    for (const file of [...docFiles(), join(REPO, 'SKILL.md'), ...skillFiles()]) {
      let inFence = false;
      readFileSync(file, 'utf8')
        .split('\n')
        .forEach((line, i) => {
          if (line.trimStart().startsWith('```')) {
            inFence = !inFence;
            return;
          }
          if (inFence) return;
          if (line.replace(/`[^`]*`/g, '').includes('—')) {
            wrong.push(`${file.replace(REPO, '')}:${i + 1}: ${line.trim()}`);
          }
        });
    }
    expect(
      wrong,
      `these use an em dash in prose. The docs style is to rewrite the sentence (a comma, a colon, ` +
        `a full stop, or two sentences) rather than to reach for the dash. Captured CLI output is ` +
        `already exempt, so a hit here is prose:\n${wrong.join('\n')}`,
    ).toEqual([]);
  });
});

/**
 * The surface has to point at the verdict, because the surface is what the agent reads.
 *
 * Agents reach for `reticle_act` far more often than `reticle_act_and_wait`, so most of the actions
 * they drive produce no verdict at all, and verdicts are rarer still than that. The
 * cause is in the descriptions: `reticle_act` sent the reader to `reticle_observe`, which is a LOOK,
 * and never mentioned `reticle_act_and_wait` at all. `act_and_wait`'s own description calls itself
 * "one hop for the act->observe->assert loop" — but only somebody who already found it ever reads
 * that.
 *
 * Tool definitions are re-sent to the model on EVERY turn, so this is a clause, not a paragraph.
 */
describe('the acting tools point at the one that produces a verdict', () => {
  const act = TOOLS.find((t) => t.name === ReticleTool.ACT);

  it('reticle_act names reticle_act_and_wait as the way to get a verdict', () => {
    expect(act, 'reticle_act is not on the surface').toBeDefined();
    expect(
      act?.description,
      'reticle_act never mentions act_and_wait, so an agent reading it has no way to learn that ' +
        'asserting is one argument away — which is how 78% of actions end with no verdict.',
    ).toContain(ReticleTool.ACT_AND_WAIT);
  });

  it('and says what act_and_wait gives you, not merely that it exists', () => {
    expect(act?.description).toMatch(/verdict|assert/i);
  });

  /**
   * Mentioning it was not enough, and we now have the number. In one day of telemetry agents called
   * `reticle_act` 179 times and `reticle_act_and_wait` 62 — and `act_and_wait` produced ALL EIGHT
   * action-derived defects while `act` produced none. `act` is the most-used tool in the product and
   * has never found anything.
   *
   * The steer was already in the description, 252 characters in, behind the full action enum. An
   * agent skimming to pick a tool reads the opening clause — "Execute one action against a ref:
   * click|dblclick|…" — which is a complete and satisfying answer to "how do I click something", and
   * stops. Position is the fix, not wording.
   *
   * 160 chars is roughly the opening sentence. This asserts the choice is made before the reference
   * material starts, and it is a BOUND, not a duration — it cannot flake.
   */
  const STEER_MUST_APPEAR_WITHIN = 160;

  it('puts the steer in the opening sentence, not behind the action enum', () => {
    const at = act?.description.indexOf(ReticleTool.ACT_AND_WAIT) ?? -1;
    expect(at).toBeGreaterThanOrEqual(0);
    expect(
      at,
      `act_and_wait is mentioned ${String(at)} chars in. An agent picking a tool reads the first ` +
        'clause and stops — which is how the most-used tool in the product has zero findings.',
    ).toBeLessThan(STEER_MUST_APPEAR_WITHIN);
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { createCommandRegistry } from './commands.js';
import { executeAction } from '@/actions/actions.js';
import { refs } from '@/dom/addressing/refs.js';
import { registerAdapter } from '@/registry/stores/adapters.js';

const reg = createCommandRegistry();

describe('upload action', () => {
  it('rejects a non-file target with a clear error', async () => {
    document.body.innerHTML = '<input type="text" />';
    const el = document.querySelector('input') as HTMLInputElement;
    await expect(executeAction(refs.refFor(el), 'upload', { name: 'x.txt' })).rejects.toThrow(
      /file/,
    );
  });
});

describe('inspect computed styles (for hover/visual checks)', () => {
  it('returns color + backgroundColor for a ref', () => {
    document.body.innerHTML = '<button style="background: rgb(1, 2, 3)">Hi</button>';
    const el = document.querySelector('button') as HTMLButtonElement;
    const handler = reg.get('inspect');
    if (handler === undefined) throw new Error('no inspect handler');
    const info = handler({ ref: refs.refFor(el) }) as {
      styles: { backgroundColor: string } | null;
    };
    expect(info.styles).not.toBeNull();
    expect(info.styles?.backgroundColor).toContain('rgb');
  });
});

/**
 * A stale ref is the most ordinary thing that follows a click, and `inspect` answered it with a
 * PROTOCOL error.
 *
 * `inspect` RETURNED `{ error }` as a successful command result, so the server passed it straight
 * into reticle_inspect's outputSchema — which requires ref/role/name/states/visible — and the MCP
 * layer rejected the tool's own response. Measured over real MCP: `reticle_act` on ref 'e99999'
 * answers "that ref is stale, re-query and retry", while `reticle_inspect` on the SAME ref answers
 * `-32602 Output validation error: … "path": ["ref"], "message": "Required"`. Same condition, one
 * hop apart, and the tool an agent reaches for to ask where something lives is the one that breaks.
 *
 * It has to THROW, like `executeAction` does, and with the same wording: the server's recovery table
 * matches /no longer resolves to an element/, so the shorter message this used to carry would have
 * missed the stale-ref recovery even once it was surfaced as an error.
 */
describe('inspect on a stale ref', () => {
  it('throws the same stale-ref error act does, instead of returning an error payload', () => {
    const handler = reg.get('inspect');
    if (handler === undefined) throw new Error('no inspect handler');
    expect(() => handler({ ref: 'e99999' })).toThrow(/no longer resolves to an element/);
  });
});

/**
 * `inspect` and `act` disagreed about the same element.
 *
 * `describe()` reads the cheap DOM-attribute source, because it runs per element on paths that
 * describe hundreds at once. Single-element paths are supposed to use `sourceFor()`, which asks the
 * framework adapter FIRST — it knows the component that RENDERED the element, not just the nearest
 * stamped host. `act` did; `inspect` did not. So on any app whose source comes from the fiber rather
 * than a babel stamp, `inspect` reported `source: null` while `act` on the very same ref returned a
 * path — and `inspect` is the tool an agent reaches for to ask where something lives. Observed on
 * three of six real apps.
 */
describe('inspect source agrees with the adapter, not just the DOM stamp', () => {
  /** A stand-in for @reticlehq/react: answers for elements carrying a marker attribute. */
  const fakeAdapter = {
    name: 'test-adapter',
    identify: (el: Element) =>
      el.hasAttribute('data-fake-component')
        ? { componentStack: ['PayButton'], source: { file: 'src/Pay.tsx', line: 12, column: 3 } }
        : null,
  };
  beforeAll(() => registerAdapter(fakeAdapter));
  afterAll(() => {
    const store = globalThis as unknown as { __reticleAdapters?: { name: string }[] };
    const list = store.__reticleAdapters ?? [];
    const i = list.findIndex((a) => a.name === fakeAdapter.name);
    if (i >= 0) list.splice(i, 1);
  });

  it('reports the ADAPTER source when there is no data-reticle-source attribute', () => {
    document.body.innerHTML = '<button data-fake-component>Pay</button>';
    const el = document.querySelector('button') as HTMLButtonElement;
    const handler = reg.get('inspect');
    if (handler === undefined) throw new Error('no inspect handler');
    const info = handler({ ref: refs.refFor(el) }) as { source?: string; component?: unknown };
    // The adapter must actually have answered, or this test proves nothing.
    expect(info.component, 'the fake adapter did not identify the element').not.toBeNull();
    expect(info.source).toBe('src/Pay.tsx:12');
  });

  it('still falls back to the DOM stamp when no adapter can answer', () => {
    document.body.innerHTML = '<div data-reticle-source="src/A.tsx:5:2"><span>x</span></div>';
    const el = document.querySelector('span') as HTMLElement;
    const handler = reg.get('inspect');
    if (handler === undefined) throw new Error('no inspect handler');
    const info = handler({ ref: refs.refFor(el) }) as { source?: string };
    expect(info.source).toBe('src/A.tsx:5');
  });
});

// @vitest-environment jsdom
import { describe, expect, it, beforeEach } from 'vitest';
import { ReticleCommand } from '@reticlehq/core';
import { createCommandRegistry } from './commands.js';
import { refs } from '@/dom/addressing/refs.js';

/**
 * The regression that beat us, caught — without a pixel.
 *
 * `bench/raw/visual-regression-bench.json` records the loss: a `filter: hue-rotate` changed 21,393
 * pixels (2.3%), a screenshot diff caught it, and `reticle_inspect` did not. That was read for a
 * year as "Reticle reads styles, not pixels".
 *
 * It was never that. The filter was on an ANCESTOR, so the element's own computed style was
 * identical before and after — correctly. We were composing nothing: CSS rasterisation runs down the
 * ancestor chain and a flat per-element read describes one link of it.
 *
 * This test is the same scenario, and it goes red if `inspect` ever stops composing. It asserts the
 * property that matters more than detection: the answer is ATTRIBUTED. A screenshot can say 21,393
 * pixels differ; it cannot say which element, which property, or what value — and an agent that
 * cannot name the cause cannot fix it.
 */
describe('inspect sees what an ancestor does to an element', () => {
  beforeEach(() => {
    document.body.innerHTML = '';
  });

  const inspect = (el: Element): Record<string, unknown> => {
    const handler = createCommandRegistry().get(ReticleCommand.INSPECT);
    if (handler === undefined) throw new Error('no inspect command');
    return (handler({ ref: refs.refFor(el) }) ?? {}) as Record<string, unknown>;
  };

  const target = (wrapperStyle: string): Element => {
    document.body.innerHTML = `<div id="wrap" style="${wrapperStyle}"><div id="target">Hello</div></div>`;
    const el = document.getElementById('target');
    if (null === el) throw new Error('fixture has no #target');
    return el;
  };

  it('says NOTHING when no ancestor is painting over it', () => {
    expect(inspect(target(''))['paintContext']).toBeUndefined();
  });

  it('CATCHES the ancestor filter, and names the element and the value', () => {
    const ctx = inspect(target('filter: hue-rotate(90deg)'))['paintContext'] as
      { on: string; property: string; value: string }[] | undefined;
    expect(ctx, 'this is the regression a screenshot caught and we did not').toBeDefined();
    expect(ctx?.[0]?.property).toBe('filter');
    expect(ctx?.[0]?.value).toContain('hue-rotate');
    // The half a screenshot structurally cannot give: WHICH element to go and edit.
    expect(ctx?.[0]?.on).toBe('#wrap');
  });

  it('catches an ancestor that makes it invisible without touching its style', () => {
    // `opacity: 0` on a parent: the child still reports its own colours, its own box, its own text.
    const ctx = inspect(target('opacity: 0'))['paintContext'] as { property: string }[] | undefined;
    expect(ctx?.some((c) => 'opacity' === c.property)).toBe(true);
  });
});

# @reticlehq/test

Reticle's spec runner for CI: write behavioral specs against your running app with `reticleTest`, drive them through Reticle's verification tools (DOM + network + console + app state) **without MCP/stdio**, and get a summary + JUnit XML your pipeline can gate on.

Part of [Reticle](https://github.com/reticlehq/reticle) — the in-app verification layer for AI agents. Use this package when you want the same inside-the-app assertions (signals, store state, network counts — the things a DOM-only tool can't see) as a plain CI test suite.

## Install

```bash
npm i -D @reticlehq/test
```

`vitest` is a peer dependency for the matcher integration; the standalone runner below needs only Node.

## Write a spec

```ts
import { reticleTest } from '@reticlehq/test';

reticleTest('add a task', async (t) => {
  await t.act('add-task', 'click');
  await t.expectElement({ testid: 'task-list' }, 'visible');
});

reticleTest('ai chat edit', async (t) => {
  await t.fill('chat-input', 'Make the hook punchier');
  await t.act('chat-send', 'click');
  await t.expectNet('POST', '/chat-script', 200);
  await t.expectSignal('chat:edit-applied', { sections: ['hook'] });
});
```

The context `t` is a thin, typed façade over Reticle's tools — it resolves `data-testid`s to live elements for you, so specs never touch refs, selectors, or the DOM directly, and assertions run against the app's real network buffer, console, signals, and registered stores.

## Run in CI

```ts
import { bootSession, runSpecs, createTestContext, writeJUnit } from '@reticlehq/test';

// … reticleTest(...) registrations above …

const booted = await bootSession({ driveUrl: 'http://localhost:4310', headless: true });
const { summary } = await runSpecs({
  invoke: booted.invoke,
  now: () => Date.now(),
  buildContext: (invoke) => createTestContext(invoke, { sessionId: 'my-app' }),
  print: (line) => process.stdout.write(line + '\n'),
});
await booted.close();
process.exit(summary.failed === 0 ? 0 : 1);
```

`bootSession` launches a headless browser against your dev server via the Reticle daemon; `runSpecs` executes every registered spec and returns a machine-readable summary. `writeJUnit(...)` emits JUnit XML for CI dashboards.

## Main exports

| Export | Purpose |
| --- | --- |
| `reticleTest`, `register`, `getRegistered`, `clearRegistry` | spec registration |
| `runSpecs`, `runOne`, `summarize`, `printSummary` | execution + reporting |
| `toJUnitXml`, `writeJUnit` | CI artifact output |
| `bootSession` | boot a driven browser session without MCP |
| `createTestContext` | the `t` façade (act / expectElement / expectNet / expectSignal / expectState …) |
| `ReticleSkip`, `ReticleAssertionError`, `isSkip` | control-flow + failure types |

## Docs

- [Testing guide](https://github.com/reticlehq/reticle/blob/main/docs/testing.md)
- [Getting started with Reticle](https://github.com/reticlehq/reticle/blob/main/docs/getting-started.md)

