/**
 * The contract fingerprint — what makes "these two pieces disagree" a DERIVED fact.
 *
 * Reticle ships as pieces installed separately: the SDK in the page, the daemon, the MCP server the
 * agent spawns. They drift constantly, and package-version equality is wrong in both directions. It
 * fires on two adjacent patch releases where nothing changed — so every patch release makes every
 * un-upgraded app cry wolf, and a warning that usually means nothing gets trained into background
 * noise. And it CANNOT fire on the case that matters most: two builds of the same version number,
 * which is exactly what a stale daemon or a cached npx package is.
 *
 * So the fingerprint hashes the thing that actually has to agree — core's wire vocabulary, the
 * commands and message kinds and event types both sides speak. Both sides compute it from their OWN
 * copy of core, so equal hashes mean the contract is shared no matter what the package.json says.
 *
 * DERIVED, never hand-bumped: a hand-maintained contract number is one someone forgets to raise, and
 * a forgotten bump is silent skew — the exact failure being fixed. Rename a command and the hash
 * moves on its own; refactor an internal and it does not.
 */

import { describe, expect, it } from 'vitest';
import { CONTRACT_FINGERPRINT, fingerprintOf } from './contract-fingerprint.js';

describe('CONTRACT_FINGERPRINT', () => {
  it('is a short, stable, printable id', () => {
    expect(CONTRACT_FINGERPRINT).toMatch(/^[0-9a-f]{8}$/);
    expect(CONTRACT_FINGERPRINT).toBe(CONTRACT_FINGERPRINT);
  });
});

describe('fingerprintOf', () => {
  it('is stable across runs and insertion order — the same contract hashes the same', () => {
    const a = fingerprintOf({ b: ['two', 'one'], a: ['x'] });
    const b = fingerprintOf({ a: ['x'], b: ['one', 'two'] });
    expect(a).toBe(b);
  });

  it('MOVES when a wire name changes — a renamed command is a different contract', () => {
    const before = fingerprintOf({ commands: ['snapshot', 'query', 'act'] });
    expect(fingerprintOf({ commands: ['snapshot', 'query', 'perform'] })).not.toBe(before);
  });

  it('MOVES when a wire name is added or removed', () => {
    const before = fingerprintOf({ commands: ['snapshot', 'query'] });
    expect(fingerprintOf({ commands: ['snapshot', 'query', 'act'] })).not.toBe(before);
    expect(fingerprintOf({ commands: ['snapshot'] })).not.toBe(before);
  });

  it('does NOT move for anything outside the listed vocabulary', () => {
    // The point of hashing the vocabulary rather than the package: internals change every release
    // and change nothing about whether two pieces can talk.
    const twice = fingerprintOf({ commands: ['snapshot', 'query'] });
    expect(fingerprintOf({ commands: ['snapshot', 'query'] })).toBe(twice);
  });

  it('distinguishes the same names under a different key — position in the contract matters', () => {
    expect(fingerprintOf({ commands: ['a'] })).not.toBe(fingerprintOf({ events: ['a'] }));
  });
});

import { describe, expect, it } from 'vitest';
import { DOCUMENT_ID_LENGTH, newDocumentId, isSameDocument } from './document-identity.js';

/**
 * Which document an observation belongs to.
 *
 * Evidence was scoped by time and by ring-buffer capacity and by nothing else, so a request observed
 * under a PREVIOUS document — or under a previous run of the application entirely — could be counted
 * against an action taken now. Field reports describe exactly that, including one where the failing
 * request Reticle cited named a database row that does not exist any more. The report was true about
 * the bytes and false about the world, which is the worst kind of wrong a verification tool can be.
 *
 * A document id is minted once per real document and dies with it. A full navigation replaces the
 * document and therefore the id; an SPA route change does NOT, which is correct — same JavaScript
 * context, same in-flight requests, same evidence.
 *
 * Randomness is injected rather than read here, for the same reason the clock is: a generator that
 * reaches for `Math.random()` cannot be tested and cannot be replayed.
 */

describe('newDocumentId', () => {
  it('is stable for one document and different across documents', () => {
    const a = newDocumentId(() => 0.5);
    const b = newDocumentId(() => 0.5);
    // Same seed, same id: the value is a pure function of what it was given, so a replay reproduces
    // it exactly rather than drifting.
    expect(a).toBe(b);
    expect(newDocumentId(() => 0.5)).not.toBe(newDocumentId(() => 0.9));
  });

  it('is short enough to stamp on every event', () => {
    // Stamped on EVERY event, so its cost is paid thousands of times per session. Long enough not to
    // collide within one session, short enough that the wire does not notice.
    expect(newDocumentId(() => 0.42)).toHaveLength(DOCUMENT_ID_LENGTH);
  });

  it('produces distinct ids across many documents', () => {
    let n = 0;
    const ids = new Set(Array.from({ length: 200 }, () => newDocumentId(() => (n++ % 97) / 97)));
    expect(ids.size).toBeGreaterThan(1);
  });

  it('never emits a character that would need escaping on the wire', () => {
    for (let i = 0; i < 50; i++) {
      expect(newDocumentId(() => i / 50)).toMatch(/^[0-9a-z]+$/);
    }
  });
});

describe('isSameDocument', () => {
  it('matches a document against itself', () => {
    expect(isSameDocument('abc123', 'abc123')).toBe(true);
  });

  it('rejects evidence minted under a superseded document', () => {
    expect(isSameDocument('abc123', 'def456')).toBe(false);
  });

  /**
   * The back-compat case, and the one where getting the default wrong is expensive in both
   * directions. An SDK older than this field stamps nothing.
   *
   * Unstamped evidence is treated as BELONGING to the current document. Excluding it would make an
   * older SDK silently stop reporting real contradictions — a verification tool that quietly finds
   * nothing is far worse than one that occasionally over-reports, and the whole point of this change
   * is to stop quietly-wrong answers rather than to trade one for another.
   */
  it('treats unstamped evidence as current, so an older SDK does not go silent', () => {
    expect(isSameDocument(undefined, 'abc123')).toBe(true);
    expect(isSameDocument('abc123', undefined)).toBe(true);
    expect(isSameDocument(undefined, undefined)).toBe(true);
  });
});

import { describe, expect, it } from 'vitest';
import { NO_EDITS_OBSERVED, isSameEditEpoch } from './edit-epoch.js';

/**
 * Which round of source edits an observation belongs to.
 *
 * The document id answers "was this page replaced". It cannot answer "was this CODE replaced": a hot
 * update swaps modules and re-renders inside the SAME document, so the id an agent is comparing
 * against never moves. An agent that edits and verifies in a loop therefore reads observations of
 * code it has already replaced, with nothing marking them.
 */

describe('isSameEditEpoch', () => {
  it('counts evidence from the current epoch as current', () => {
    expect(isSameEditEpoch(3, 3)).toBe(true);
  });

  it('counts evidence from an earlier epoch as NOT current', () => {
    expect(isSameEditEpoch(2, 3)).toBe(false);
  });

  it('counts UNSTAMPED evidence as current, exactly as isSameDocument does', () => {
    // An SDK older than this field stamps nothing, and an app with no hot-update channel stamps
    // nothing either. Reading either as "foreign" would make those installations silently stop
    // reporting real contradictions, which is the failure this whole family of checks exists to
    // avoid — a tool that quietly finds nothing is worse than one that occasionally over-reports.
    expect(isSameEditEpoch(undefined, 3)).toBe(true);
    expect(isSameEditEpoch(2, undefined)).toBe(true);
    expect(isSameEditEpoch(undefined, undefined)).toBe(true);
  });

  it('counts everything as current while no edit has been observed', () => {
    // Absence of hot-update support means UNKNOWN, never "no edits happened" — so the epoch nobody
    // has advanced must not start excluding or labelling anything.
    expect(isSameEditEpoch(NO_EDITS_OBSERVED, NO_EDITS_OBSERVED)).toBe(true);
    expect(isSameEditEpoch(undefined, NO_EDITS_OBSERVED)).toBe(true);
  });
});

import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';
import { PROJECT_ID_HASH_LENGTH, projectIdFrom, slugifyPackageName } from './project-id.js';

/** The callers' hashing, reproduced here so the assertions are about the RULE, not about sha1. */
const sha1Short = (input: string): string =>
  createHash('sha1').update(input).digest('hex').slice(0, PROJECT_ID_HASH_LENGTH);

describe('slugifyPackageName', () => {
  it('strips the scope and collapses non-alphanumerics', () => {
    expect(slugifyPackageName('@acme/web')).toBe('acme-web');
    expect(slugifyPackageName('Weird__Name!!')).toBe('weird-name');
  });
});

describe('projectIdFrom', () => {
  it('uses the package name plus a fingerprint of the root', () => {
    expect(projectIdFrom('@acme/web', '/x/y', sha1Short)).toBe(`acme-web-${sha1Short('/x/y')}`);
  });

  it('falls back to the root folder name when there is no package name', () => {
    expect(projectIdFrom(undefined, '/a/b/my-app', sha1Short)).toBe(
      `my-app-${sha1Short('/a/b/my-app')}`,
    );
  });

  it('falls back to "app" when neither name yields anything usable', () => {
    expect(projectIdFrom('', '/', sha1Short)).toBe(`app-${sha1Short('/')}`);
  });

  /**
   * Two checkouts of the same package are different projects. Without the root in the hash, a
   * developer with the app cloned twice gets one id for both and their sessions interleave.
   */
  it('distinguishes two checkouts of the same package', () => {
    const a = projectIdFrom('web', '/home/me/one', sha1Short);
    const b = projectIdFrom('web', '/home/me/two', sha1Short);
    expect(a).not.toBe(b);
  });

  /** The folder-name fallback must not depend on which OS wrote the path. */
  it('reads the last path segment the same on both separators', () => {
    const posix = projectIdFrom(undefined, '/a/b/my-app', () => 'h');
    const windows = projectIdFrom(undefined, 'C:\\a\\b\\my-app', () => 'h');
    expect(posix).toBe(windows);
  });

  /** A trailing separator is not part of the folder name. */
  it('ignores a trailing separator', () => {
    expect(projectIdFrom(undefined, '/a/b/', () => 'h')).toBe(
      projectIdFrom(undefined, '/a/b', () => 'h'),
    );
  });
});
